window.QBANK = window.QBANK || {};
window.QBANK["sma-geografi"] = {
  level: "SMA", subject: "Geografi", duration: 900,
  questions: [
    { q: "Unsur peta yang menjelaskan arti dari simbol-simbol yang digunakan pada peta disebut ...", options: ["judul peta", "skala peta", "orientasi", "legenda"], answer: 3, solution: "1. Simbol pada peta (misalnya garis biru untuk sungai) tidak dapat dipahami tanpa keterangan artinya. 2. Keterangan arti simbol-simbol tersebut dimuat dalam legenda peta. 3. Jadi unsur yang menjelaskan arti simbol adalah legenda. (Judul = nama peta, skala = perbandingan jarak, orientasi = penunjuk arah mata angin.)" },
    { q: "Jarak dua kota pada peta adalah $4\\ \\text{cm}$. Jika peta berskala $1:50.000$, jarak sebenarnya kedua kota adalah ...", options: ["$20\\ \\text{km}$", "$0{,}2\\ \\text{km}$", "$2\\ \\text{km}$", "$200\\ \\text{km}$"], answer: 2, solution: "1. Jarak sebenarnya $=$ jarak peta $\\times$ penyebut skala $= 4\\ \\text{cm} \\times 50.000 = 200.000\\ \\text{cm}$. 2. Ubah ke kilometer: $200.000\\ \\text{cm} = 2.000\\ \\text{m} = 2\\ \\text{km}$. 3. Jadi jarak sebenarnya kedua kota adalah $2\\ \\text{km}$." },
    { q: "Jarak sebenarnya antara Kota A dan Kota B adalah $15\\ \\text{km}$. Pada peta berskala $1:250.000$, jarak kedua kota pada peta adalah ...", options: ["$6\\ \\text{cm}$", "$3{,}75\\ \\text{cm}$", "$60\\ \\text{cm}$", "$0{,}6\\ \\text{cm}$"], answer: 0, solution: "1. Ubah jarak sebenarnya ke cm: $15\\ \\text{km} = 1.500.000\\ \\text{cm}$. 2. Jarak peta $=$ jarak sebenarnya $\\div$ penyebut skala $= 1.500.000 \\div 250.000 = 6\\ \\text{cm}$. 3. Jadi jarak kedua kota pada peta adalah $6\\ \\text{cm}$." },
    { q: "Jenis proyeksi peta yang mempertahankan luas sebenarnya suatu wilayah (misalnya untuk peta persebaran hasil pertanian) disebut proyeksi ...", options: ["konform", "ekuidistan", "ekuivalen", "azimuthal"], answer: 2, solution: "1. Proyeksi konform mempertahankan bentuk/sudut, sedangkan proyeksi ekuidistan mempertahankan jarak. 2. Proyeksi yang mempertahankan luas daerah disebut proyeksi ekuivalen (contoh: Mollweide, Gall-Peters). 3. Jadi jawabannya proyeksi ekuivalen. (Azimuthal adalah proyeksi berdasarkan bidangnya, bukan sifat yang dipertahankan.)" },
    { q: "Proyeksi peta yang mempertahankan bentuk (sudut) sehingga banyak digunakan untuk peta navigasi pelayaran adalah proyeksi ...", options: ["sinusoidal", "Mercator", "Mollweide", "Gall-Peters"], answer: 1, solution: "1. Peta navigasi membutuhkan arah dan bentuk yang tepat agar dapat dipakai berlayar dengan kompas. 2. Proyeksi yang mempertahankan bentuk/sudut disebut konform, contohnya proyeksi silinder Mercator. 3. Jadi jawabannya proyeksi Mercator. (Mollweide, Gall-Peters, dan sinusoidal bersifat ekuivalen/menjaga luas.)" },
    { q: "Citra penginderaan jauh yang dihasilkan oleh sensor kamera (fotografik), contohnya foto udara, disebut citra ...", options: ["foto", "nonfoto", "radar", "termal"], answer: 0, solution: "1. Citra dibedakan berdasarkan jenis sensor perekamnya. 2. Citra yang direkam dengan kamera/film fotografik disebut citra foto (contoh: foto udara). 3. Citra radar, termal, dan citra satelit elektro-optik direkam sensor non-kamera sehingga termasuk citra nonfoto." },
    { q: "Perbedaan utama antara citra foto dan citra nonfoto terletak pada ...", options: ["warna yang dihasilkan", "jenis sensor yang digunakan untuk merekam", "ukuran citra yang dicetak", "tahun pembuatan citra"], answer: 1, solution: "1. Citra foto direkam oleh sensor kamera (fotografik), sedangkan citra nonfoto direkam oleh sensor elektronik non-kamera seperti pemindai elektro-optik, radar, dan sensor termal. 2. Jadi perbedaan utamanya adalah jenis sensor yang digunakan untuk merekam. 3. Warna, ukuran cetak, dan tahun pembuatan bukan pembeda jenis citra." },
    { q: "Tahapan kerja SIG yang meliputi pemasukan data spasial (peta) dan data atribut (tabel) ke dalam sistem disebut tahap ...", options: ["analisis data", "penyajian data", "manajemen data", "pemasukan data"], answer: 3, solution: "1. Alur kerja SIG terdiri dari pemasukan data, manajemen/penyimpanan data, analisis data, dan penyajian (output) data. 2. Memasukkan peta hasil digitasi dan tabel atribut ke dalam komputer merupakan tahap pemasukan data (input). 3. Jadi jawabannya tahap pemasukan data." },
    { q: "Indonesia terletak pada pertemuan tiga lempeng tektonik besar, yaitu lempeng ...", options: ["Amerika Utara, Afrika, dan Antartika", "Indo-Australia, Eurasia, dan Pasifik", "Arab, Karibia, dan Scotia", "Nazca, Cocos, dan Filipina"], answer: 1, solution: "1. Indonesia berada di zona tumbukan lempeng yang sangat aktif. 2. Tiga lempeng yang bertemu di wilayah Indonesia adalah lempeng Indo-Australia (dari selatan), lempeng Eurasia (dari utara), dan lempeng Pasifik (dari timur). 3. Pertemuan ketiganya membuat Indonesia rawan gempa dan kaya gunung api." },
    { q: "Gerakan lempeng tektonik yang saling menjauhi sehingga membentuk punggung tengah samudra (mid oceanic ridge) disebut gerakan ...", options: ["divergen", "konvergen", "transform", "subduksi"], answer: 0, solution: "1. Lempeng tektonik dapat bergerak saling menjauh, bertumbukan, atau bergeser. 2. Gerakan saling menjauh disebut divergen; magma naik mengisi celah dan membentuk punggung tengah samudra. 3. Jadi jawabannya gerakan divergen. (Konvergen = bertumbukan, transform = bergeser horizontal.)" },
    { q: "Gunung api yang terbentuk dari lava encer (basaltis) dengan lereng landai dan letusan bersifat efusif (lelehan) adalah gunung api tipe ...", options: ["strato", "maar", "perisai", "kaldera"], answer: 2, solution: "1. Lava encer mudah mengalir jauh sebelum membeku sehingga membentuk lereng yang landai dan lebar seperti perisai. 2. Letusannya bersifat efusif (lelehan lava), tidak eksplosif. 3. Jadi tipe tersebut adalah gunung api perisai (contoh: Mauna Loa di Hawaii)." },
    { q: "Gunung Merapi dan Gunung Semeru digolongkan sebagai gunung api strato karena ...", options: ["lavanya sangat encer dan mengalir jauh", "kawahnya sangat lebar dan dangkal", "hanya meletus sekali lalu mati", "tersusun dari lapisan lava kental dan material piroklastik dengan letusan eksplosif"], answer: 3, solution: "1. Gunung strato (kerucut) tersusun dari lapisan lava kental dan material piroklastik (abu, kerikil, bom) yang berselang-seling. 2. Lava kental menyumbat kepundan sehingga tekanannya besar dan letusannya eksplosif, seperti pada Merapi dan Semeru. 3. Jadi ciri tersebut menunjukkan gunung api strato." },
    { q: "Batuan yang terbentuk dari pembekuan magma jauh di dalam kerak bumi secara perlahan sehingga kristal mineralnya besar (contoh: granit) disebut batuan beku ...", options: ["ekstrusif", "intrusif", "sedimen", "metamorf"], answer: 1, solution: "1. Batuan beku dibedakan menurut tempat pembekuan magmanya. 2. Magma yang membeku di dalam bumi (jauh di bawah permukaan) mendingin perlahan sehingga kristalnya besar, disebut batuan beku intrusif/plutonik (contoh: granit). 3. Magma yang membeku di permukaan disebut ekstrusif/vulkanik (contoh: basal)." },
    { q: "Batu gamping (kapur) yang terbentuk dari timbunan sisa cangkang organisme laut termasuk batuan sedimen ...", options: ["organik", "klastik", "kimiawi", "beku"], answer: 0, solution: "1. Batuan sedimen organik terbentuk dari sisa-sisa organisme (tumbuhan/hewan). 2. Batu gamping tersusun dari timbunan cangkang dan rangka organisme laut yang memfosil. 3. Jadi batu gamping termasuk sedimen organik. (Sedimen klastik berasal dari pecahan batuan, sedimen kimiawi dari pengendapan zat terlarut.)" },
    { q: "Titik di permukaan bumi yang terletak tepat di atas hiposentrum (pusat gempa) disebut ...", options: ["fokus", "hiposentrum", "episentrum", "patahan"], answer: 2, solution: "1. Hiposentrum (fokus) adalah pusat gempa di dalam bumi, tempat energi gempa pertama kali dilepaskan. 2. Titik di permukaan bumi yang tepat berada di atas hiposentrum disebut episentrum; di sinilah guncangan biasanya paling kuat terasa. 3. Jadi jawabannya episentrum." },
    { q: "Gempa bumi yang disebabkan oleh pergeseran lempeng tektonik disebut gempa ...", options: ["vulkanik", "runtuhan", "buatan", "tektonik"], answer: 3, solution: "1. Gempa dibedakan menurut penyebabnya. 2. Pergeseran atau tumbukan lempeng tektonik melepaskan energi besar yang merambatkan getaran, disebut gempa tektonik (paling sering terjadi dan merusak). 3. Gempa vulkanik disebabkan letusan gunung api, sedangkan gempa runtuhan disebabkan runtuhnya gua atau tambang." },
    { q: "Proses perubahan air (laut, sungai, danau) menjadi uap air akibat pemanasan matahari disebut ...", options: ["kondensasi", "evaporasi", "presipitasi", "infiltrasi"], answer: 1, solution: "1. Siklus hidrologi diawali dari penguapan air di permukaan bumi. 2. Perubahan air menjadi uap air karena panas matahari disebut evaporasi (penguapan). 3. Jadi jawabannya evaporasi. (Kondensasi = uap menjadi awan, presipitasi = hujan, infiltrasi = peresapan ke dalam tanah.)" },
    { q: "Siklus hidrologi yang meliputi penguapan air laut, pembentukan awan, hujan di daerah pegunungan, lalu air mengalir kembali ke laut disebut siklus ...", options: ["pendek", "sedang", "panjang", "tertutup"], answer: 2, solution: "1. Siklus pendek: laut menjadi awan lalu hujan kembali ke laut. Siklus sedang: laut menjadi awan lalu hujan di daratan dekat pantai. 2. Siklus dengan perjalanan terjauh (laut, pegunungan, sungai, kembali ke laut) disebut siklus panjang. 3. Jadi jawabannya siklus panjang." },
    { q: "Pada bagian hulu, sungai umumnya memiliki ciri ...", options: ["lembah berbentuk V, arus deras, dan erosi vertikal yang kuat", "banyak meander dan aliran lambat", "membentuk delta di muara", "dasar sungai dipenuhi endapan lumpur tebal"], answer: 0, solution: "1. Bagian hulu berada di daerah tinggi dengan kemiringan lereng yang besar. 2. Air mengalir deras dan mengikis dasar sungai ke arah vertikal sehingga terbentuk lembah berbentuk V. 3. Jadi ciri sungai di hulu adalah lembah V, arus deras, dan erosi vertikal yang kuat. (Meander dan delta adalah ciri bagian hilir.)" },
    { q: "Pola aliran sungai yang berbentuk seperti cabang-cabang pohon dan berkembang di daerah berbatuan homogen disebut pola aliran ...", options: ["radial", "trellis", "rektangular", "dendritik"], answer: 3, solution: "1. Pola aliran sungai dipengaruhi oleh struktur batuannya. 2. Pada batuan yang homogen (seragam), sungai bercabang bebas ke segala arah menyerupai cabang pohon, disebut pola dendritik. 3. Jadi jawabannya dendritik. (Radial = menyebar dari puncak, trellis = di daerah lipatan, rektangular = mengikuti patahan.)" },
    { q: "Danau Toba di Sumatra Utara terbentuk akibat ...", options: ["pelarutan batu gamping oleh air hujan", "aktivitas vulkanik yang disertai amblesan tektonik", "terbendungnya aliran sungai oleh endapan", "bekas galian tambang yang terisi air"], answer: 1, solution: "1. Danau Toba menempati kaldera raksasa bekas letusan supervulkan. 2. Letusan dahsyat tersebut disertai amblesan (penurunan) kerak bumi secara tektonik sehingga terbentuk cekungan besar yang terisi air. 3. Jadi Danau Toba adalah danau tektovulkanik: gabungan proses vulkanik dan tektonik." },
    { q: "Air tanah yang terletak di antara dua lapisan kedap air sehingga memiliki tekanan ke atas disebut air tanah ...", options: ["freatik", "permukaan", "artesis", "tadah hujan"], answer: 2, solution: "1. Air tanah freatik berada di atas lapisan kedap air pertama dan tidak bertekanan. 2. Air tanah yang terjepit di antara dua lapisan kedap air (akuifer tertekan) disebut air tanah artesis (dalam). 3. Karena bertekanan, air artesis dapat memancar sendiri ke permukaan melalui sumur artesis." },
    { q: "Sumur yang airnya dapat memancar ke permukaan tanah dengan sendirinya tanpa dipompa disebut sumur ...", options: ["artesis", "gali", "pompa", "resapan"], answer: 0, solution: "1. Air tanah artesis terjepit di antara dua lapisan kedap air sehingga memiliki tekanan. 2. Ketika sumur menembus akuifer tertekan tersebut, tekanan mendorong air naik dan memancar ke permukaan tanpa pompa. 3. Jadi sumur tersebut disebut sumur artesis." },
    { q: "Lapisan atmosfer tempat terjadinya gejala cuaca seperti awan, hujan, dan angin adalah lapisan ...", options: ["stratosfer", "mesosfer", "termosfer", "troposfer"], answer: 3, solution: "1. Atmosfer tersusun dari beberapa lapisan: troposfer, stratosfer, mesosfer, termosfer, dan eksosfer. 2. Lapisan terbawah yang bersentuhan dengan permukaan bumi, tempat uap air berkumpul dan gejala cuaca terjadi, adalah troposfer. 3. Jadi jawabannya troposfer. (Stratosfer mengandung lapisan ozon.)" },
    { q: "Suhu udara di kaki gunung (ketinggian $0\\ \\text{m}$) adalah $27^\\circ\\text{C}$. Jika suhu turun $0{,}6^\\circ\\text{C}$ setiap kenaikan $100\\ \\text{m}$, suhu udara di puncak gunung setinggi $2.700\\ \\text{m}$ diperkirakan ...", options: ["$10{,}8^\\circ\\text{C}$", "$16{,}2^\\circ\\text{C}$", "$43{,}2^\\circ\\text{C}$", "$22{,}5^\\circ\\text{C}$"], answer: 0, solution: "1. Penurunan suhu $= \\frac{2.700}{100} \\times 0{,}6^\\circ\\text{C} = 27 \\times 0{,}6^\\circ\\text{C} = 16{,}2^\\circ\\text{C}$. 2. Suhu puncak $=$ suhu kaki gunung $-$ penurunan suhu $= 27^\\circ\\text{C} - 16{,}2^\\circ\\text{C} = 10{,}8^\\circ\\text{C}$. 3. Jadi suhu di puncak diperkirakan $10{,}8^\\circ\\text{C}$." },
    { q: "Hujan yang terjadi karena massa udara lembap dipaksa naik melewati pegunungan, lalu mendingin dan mengembun disebut hujan ...", options: ["zenithal", "orografis", "frontal", "siklon"], answer: 1, solution: "1. Ketika angin membawa uap air menabrak pegunungan, udara dipaksa naik ke tempat yang lebih dingin. 2. Uap air mengembun dan jatuh sebagai hujan di lereng pegunungan; hujan jenis ini disebut hujan orografis (hujan pegunungan). 3. Jadi jawabannya hujan orografis. (Hujan zenithal terjadi karena pemanasan kuat, hujan frontal karena pertemuan dua massa udara.)" },
    { q: "Angin yang bertiup dari Benua Asia menuju Australia pada bulan Oktober-April dan membawa banyak uap air sehingga menimbulkan musim hujan di Indonesia adalah angin ...", options: ["muson timur", "angin darat", "muson barat", "angin fohn"], answer: 2, solution: "1. Pada bulan Oktober-April, tekanan udara tinggi di Asia dan rendah di Australia sehingga angin bertiup dari Asia ke Australia. 2. Angin ini melewati samudra luas dan membawa uap air yang banyak, lalu menurunkan hujan di Indonesia; disebut angin muson barat. 3. Jadi jawabannya angin muson barat. (Angin muson timur bertiup April-Oktober dan bersifat kering.)" },
    { q: "Menurut klasifikasi iklim Koppen, sebagian besar wilayah Indonesia yang bercurah hujan tinggi sepanjang tahun termasuk tipe iklim ...", options: ["Af", "Aw", "Bw", "Cfb"], answer: 0, solution: "1. Pada klasifikasi Koppen, huruf A berarti iklim tropis (suhu rata-rata bulan terdingin $> 18^\\circ\\text{C}$). 2. Huruf f berarti basah sepanjang tahun tanpa bulan kering yang nyata (hutan hujan tropis). 3. Jadi wilayah Indonesia yang hujannya merata sepanjang tahun bertipe Af. (Aw = sabana tropis bermusim kering, Bw = gurun.)" },
    { q: "Suatu daerah memiliki rata-rata $4$ bulan kering dan $8$ bulan basah dalam setahun. Nilai $Q$ Schmidt-Ferguson dan tipe iklim daerah tersebut adalah ...", options: ["$Q = 200\\%$, tipe F (kering)", "$Q = 50\\%$, tipe C (agak basah)", "$Q = 33\\%$, tipe B (basah)", "$Q = 80\\%$, tipe D (sedang)"], answer: 1, solution: "1. Rumus Schmidt-Ferguson: $Q = \\frac{\\text{bulan kering}}{\\text{bulan basah}} \\times 100\\% = \\frac{4}{8} \\times 100\\% = 50\\%$. 2. Nilai $Q$ antara $33{,}3\\%$ sampai $60\\%$ termasuk tipe C (agak basah). 3. Jadi daerah tersebut memiliki $Q = 50\\%$ dengan tipe iklim C (agak basah)." },
    { q: "Gas rumah kaca yang paling banyak dihasilkan dari pembakaran bahan bakar fosil dan menjadi penyebab utama pemanasan global adalah ...", options: ["oksigen ($\\text{O}_2$)", "nitrogen ($\\text{N}_2$)", "hidrogen ($\\text{H}_2$)", "karbon dioksida ($\\text{CO}_2$)"], answer: 3, solution: "1. Pembakaran batu bara, minyak bumi, dan gas alam menghasilkan gas buangan. 2. Gas buangan utama dari pembakaran tersebut adalah karbon dioksida ($\\text{CO}_2$) yang memerangkap panas matahari di atmosfer (efek rumah kaca). 3. Jadi penyebab utama pemanasan global dari bahan bakar fosil adalah karbon dioksida." },
    { q: "Salah satu dampak pemanasan global yang dirasakan wilayah pesisir Indonesia adalah ...", options: ["menurunnya suhu rata-rata udara", "meluasnya lapisan es di kutub", "naiknya permukaan air laut dan banjir rob", "berhentinya siklus hidrologi"], answer: 2, solution: "1. Pemanasan global mencairkan es di kutub dan memuaikan volume air laut. 2. Akibatnya permukaan air laut naik dan daerah pantai yang rendah tergenang (banjir rob), seperti yang terjadi di pesisir utara Jawa. 3. Jadi dampaknya adalah naiknya permukaan air laut dan banjir rob." },
    { q: "Garis Wallace memisahkan fauna tipe Asiatis dan tipe peralihan di Indonesia. Garis khayal ini terletak di antara ...", options: ["Kalimantan dan Sulawesi", "Sulawesi dan Maluku", "Maluku dan Papua", "Sumatra dan Jawa"], answer: 0, solution: "1. Alfred Russel Wallace mengamati perbedaan mencolok antara fauna di barat dan timur Indonesia. 2. Garis batasnya ditarik di antara Kalimantan-Sulawesi serta Bali-Lombok: di baratnya fauna Asiatis, di timurnya fauna peralihan. 3. Jadi garis Wallace terletak di antara Kalimantan dan Sulawesi." },
    { q: "Garis khayal yang memisahkan fauna tipe peralihan dan fauna tipe Australis di Indonesia adalah garis ...", options: ["katulistiwa", "Wallace", "Weber", "bujur"], answer: 2, solution: "1. Indonesia memiliki tiga tipe fauna: Asiatis (barat), peralihan (tengah), dan Australis (timur/Papua). 2. Batas antara fauna peralihan dan fauna Australis disebut garis Weber (di sekitar Kepulauan Maluku). 3. Jadi jawabannya garis Weber. (Garis Wallace membatasi fauna Asiatis dan peralihan.)" },
    { q: "Hewan berikut yang termasuk fauna tipe Australis (Indonesia bagian timur) adalah ...", options: ["gajah", "komodo", "anoa", "kasuari"], answer: 3, solution: "1. Fauna Australis memiliki banyak kesamaan dengan fauna Benua Australia. 2. Kasuari (burung besar yang tidak bisa terbang) hidup di Papua dan merupakan fauna Australis. 3. Jadi jawabannya kasuari. (Gajah = Asiatis; komodo dan anoa = peralihan.)" },
    { q: "Anoa, komodo, dan babi rusa merupakan contoh fauna Indonesia bertipe ...", options: ["Asiatis", "peralihan", "Australis", "kosmopolitan"], answer: 1, solution: "1. Fauna Indonesia bagian tengah (Sulawesi, Nusa Tenggara, Maluku) merupakan campuran dengan ciri khas tersendiri. 2. Anoa (Sulawesi), komodo (Nusa Tenggara), dan babi rusa (Sulawesi) hidup di wilayah peralihan. 3. Jadi ketiganya termasuk fauna tipe peralihan." },
    { q: "Bioma yang didominasi pohon berdaun lebar yang hijau sepanjang tahun dengan curah hujan tinggi, seperti di Kalimantan dan Papua, adalah bioma ...", options: ["hutan hujan tropis", "sabana", "stepa", "taiga"], answer: 0, solution: "1. Ciri bioma ini: curah hujan lebih dari $2.000\\ \\text{mm}$ per tahun, pohon berdaun lebar, selalu hijau (evergreen), dan keanekaragaman hayati sangat tinggi. 2. Ciri tersebut tepat menggambarkan hutan hujan tropis di Kalimantan, Sumatra, dan Papua. 3. Jadi jawabannya bioma hutan hujan tropis." },
    { q: "Persebaran flora di Indonesia bagian timur (Papua) banyak dipengaruhi oleh flora kawasan ...", options: ["Asiatis", "Neotropik", "Australis", "Paleartik"], answer: 2, solution: "1. Flora Indonesia barat (Sumatra, Kalimantan) berkerabat dengan flora Asia (Asiatis). 2. Sebaliknya flora Papua berkerabat dengan flora Australia, misalnya pohon sagu dan kayu putih. 3. Jadi flora Indonesia timur dipengaruhi kawasan Australis." },
    { q: "Faktor utama yang menyebabkan keanekaragaman flora di Indonesia sangat tinggi adalah ...", options: ["tanahnya selalu subur di semua daerah", "iklim tropis yang hangat dan lembap sepanjang tahun", "tidak pernah terjadi bencana alam", "penduduknya jarang menebang hutan"], answer: 1, solution: "1. Tumbuhan membutuhkan panas, cahaya, dan air yang cukup untuk tumbuh. 2. Indonesia beriklim tropis: suhu hangat dan hujan tersedia sepanjang tahun sehingga tumbuhan dapat tumbuh subur dan beragam. 3. Jadi faktor utamanya adalah iklim tropis yang hangat dan lembap sepanjang tahun." },
    { q: "Piramida penduduk dengan alas yang lebar dan puncak yang meruncing menunjukkan bahwa daerah tersebut ...", options: ["penduduk usia tua dominan", "jumlah penduduknya tetap stabil", "angka kematiannya sangat rendah", "angka kelahiran tinggi dan penduduk usia muda dominan"], answer: 3, solution: "1. Alas piramida menggambarkan kelompok usia muda (0-14 tahun). 2. Alas yang lebar berarti jumlah anak-anak banyak, menandakan angka kelahiran tinggi; bentuk ini disebut piramida ekspansif. 3. Jadi daerah tersebut memiliki angka kelahiran tinggi dan penduduk usia muda dominan." },
    { q: "Pada tahun 2025, jumlah kelahiran di Kota X sebanyak $1.500$ jiwa dan jumlah penduduknya $500.000$ jiwa. Angka kelahiran kasar (CBR) Kota X adalah ... per $1.000$ penduduk.", options: ["$3$", "$30$", "$0{,}3$", "$300$"], answer: 0, solution: "1. Rumus angka kelahiran kasar: $\\text{CBR} = \\frac{\\text{jumlah kelahiran}}{\\text{jumlah penduduk}} \\times 1.000$. 2. $\\text{CBR} = \\frac{1.500}{500.000} \\times 1.000 = 0{,}003 \\times 1.000 = 3$. 3. Jadi CBR Kota X adalah $3$ per $1.000$ penduduk." },
    { q: "Kabupaten Y berpenduduk $2.400.000$ jiwa dengan luas wilayah $600\\ \\text{km}^2$. Kepadatan penduduk Kabupaten Y adalah ...", options: ["$400\\ \\text{jiwa/km}^2$", "$40.000\\ \\text{jiwa/km}^2$", "$4.000\\ \\text{jiwa/km}^2$", "$14.400\\ \\text{jiwa/km}^2$"], answer: 2, solution: "1. Rumus kepadatan penduduk $= \\frac{\\text{jumlah penduduk}}{\\text{luas wilayah}}$. 2. Kepadatan $= \\frac{2.400.000}{600} = 4.000\\ \\text{jiwa/km}^2$. 3. Jadi kepadatan penduduk Kabupaten Y adalah $4.000\\ \\text{jiwa/km}^2$." },
    { q: "Bonus demografi terjadi ketika ...", options: ["angka kelahiran sangat tinggi", "jumlah penduduk usia produktif lebih besar daripada penduduk usia nonproduktif", "seluruh penduduk berusia lanjut", "tidak ada penduduk yang bermigrasi"], answer: 1, solution: "1. Penduduk usia produktif (15-64 tahun) adalah penggerak ekonomi, sedangkan usia nonproduktif (0-14 dan 65 tahun ke atas) menjadi tanggungan. 2. Ketika penduduk produktif jumlahnya lebih besar, rasio ketergantungan rendah dan peluang ekonomi terbuka lebar; kondisi inilah yang disebut bonus demografi. 3. Jadi bonus demografi terjadi saat penduduk usia produktif lebih besar daripada usia nonproduktif." },
    { q: "Angka kematian kasar (CDR) yang tinggi pada suatu daerah umumnya menunjukkan bahwa ...", options: ["penduduknya sangat sejahtera", "fasilitas kesehatannya memadai", "angka harapan hidupnya tinggi", "kualitas kesehatan dan kesejahteraan penduduknya masih rendah"], answer: 3, solution: "1. Angka kematian kasar menggambarkan banyaknya kematian per $1.000$ penduduk. 2. Kematian yang tinggi biasanya disebabkan gizi buruk, penyakit, dan layanan kesehatan yang kurang. 3. Jadi CDR yang tinggi umumnya menunjukkan kualitas kesehatan dan kesejahteraan penduduk masih rendah." },
    { q: "Perpindahan penduduk dari desa ke kota untuk mencari pekerjaan dan penghidupan yang lebih baik disebut ...", options: ["urbanisasi", "transmigrasi", "ruralisasi", "emigrasi"], answer: 0, solution: "1. Perpindahan penduduk dibedakan menurut arah dan tujuannya. 2. Perpindahan dari desa ke kota disebut urbanisasi. 3. Jadi jawabannya urbanisasi. (Transmigrasi = perpindahan antar pulau oleh pemerintah, ruralisasi = kota ke desa, emigrasi = ke luar negeri.)" },
    { q: "Rasio ketergantungan (dependency ratio) yang rendah menguntungkan pembangunan suatu negara karena ...", options: ["penduduknya menjadi homogen", "jumlah penduduknya berkurang", "tidak ada penduduk usia lanjut", "beban tanggungan penduduk usia produktif kecil"], answer: 3, solution: "1. Dependency ratio membandingkan jumlah penduduk nonproduktif dengan penduduk produktif. 2. Jika rasionya rendah, setiap penduduk produktif hanya menanggung sedikit penduduk nonproduktif sehingga tabungan, investasi, dan pembangunan dapat meningkat. 3. Jadi keuntungannya adalah beban tanggungan penduduk usia produktif kecil." },
    { q: "Menurut teori tempat sentral Christaller, daerah pengaruh (hinterland) suatu pusat pelayanan berbentuk ...", options: ["lingkaran", "heksagonal (segi enam)", "persegi", "segitiga"], answer: 1, solution: "1. Christaller berpendapat setiap pusat pelayanan memiliki daerah pengaruh yang dilayaninya. 2. Agar seluruh wilayah terlayani tanpa tumpang tindih dan tanpa celah, bentuk yang paling efisien adalah segi enam beraturan (heksagonal). 3. Jadi daerah pengaruh berbentuk heksagonal." },
    { q: "Menurut teori Von Thunen, kegiatan pertanian yang paling cocok diusahakan di lahan terdekat dengan pusat kota adalah ...", options: ["sayuran dan peternakan susu (mudah rusak, biaya angkut mahal)", "perkebunan karet", "hutan kayu bakar", "pertanian padi ladang"], answer: 0, solution: "1. Von Thunen menyatakan jenis penggunaan lahan ditentukan oleh jarak ke pasar (kota) dan biaya angkut. 2. Produk yang mudah rusak dan mahal biaya angkutnya (sayuran, susu) harus diusahakan paling dekat dengan kota agar tetap segar dan menguntungkan. 3. Jadi jawabannya sayuran dan peternakan susu." },
    { q: "Bentuk interaksi yang menunjukkan ketergantungan kota terhadap desa adalah ...", options: ["desa membeli barang industri dari kota", "penduduk desa bersekolah di kota", "kota membutuhkan bahan pangan dan tenaga kerja dari desa", "petani desa menjual hasil panen ke pasar kota"], answer: 2, solution: "1. Interaksi desa-kota bersifat saling membutuhkan. 2. Kota tidak menghasilkan bahan pangan sendiri sehingga bergantung pada pasokan pangan dan tenaga kerja dari desa. 3. Jadi bentuk ketergantungan kota terhadap desa adalah kebutuhan bahan pangan dan tenaga kerja dari desa." },
    { q: "Konsep kutub pertumbuhan (growth pole) yang menyatakan pembangunan berawal dari pusat-pusat kegiatan ekonomi yang kemudian menyebar ke sekitarnya dikemukakan oleh ...", options: ["Christaller", "Von Thunen", "Weber", "Perroux"], answer: 3, solution: "1. Beberapa ahli mengemukakan teori tentang pusat pertumbuhan wilayah. 2. Konsep kutub pertumbuhan (growth pole) dikemukakan oleh Francois Perroux: kegiatan ekonomi terkonsentrasi di suatu kutub lalu menetes ke wilayah sekitarnya (trickling down effect). 3. Jadi jawabannya Perroux. (Christaller = tempat sentral, Von Thunen = lokasi pertanian.)" },
    { q: "Penyebaran teknologi pertanian modern dari kota ke desa-desa sekitarnya merupakan contoh ...", options: ["aglomerasi", "difusi inovasi", "urbanisasi", "migrasi sirkuler"], answer: 1, solution: "1. Penyebaran unsur kebudayaan atau teknologi dari suatu pusat ke wilayah lain disebut difusi. 2. Teknologi pertanian modern yang menyebar dari kota ke desa adalah penyebaran suatu inovasi. 3. Jadi peristiwa tersebut merupakan contoh difusi inovasi." },
{ q: "Peta yang menggambarkan fenomena yang selalu berubah, misalnya peta prakiraan cuaca dan peta arus lalu lintas, disebut peta ...", options: ["korografi","statis","kadaster","dinamis"], answer: 3, solution: "1. Peta dinamis menggambarkan fenomena yang berubah-ubah terhadap waktu. 2. Data peta cuaca dan lalu lintas diperbarui terus-menerus. 3. Jadi jawabannya peta dinamis." },
  { q: "Peta kadaster memuat informasi tentang ...", options: ["persebaran hasil tambang","bentuk muka bumi dan ketinggian","jalur pelayaran internasional","batas kepemilikan tanah dan sertifikat"], answer: 3, solution: "1. Kadaster adalah peta pertanahan berskala besar. 2. Isinya batas persil, luas, dan status kepemilikan tanah. 3. Dipakai untuk sertifikat tanah, jadi jawabannya batas kepemilikan tanah dan sertifikat." },
  { q: "Perbedaan utama peta topografi dan peta korografi adalah ...", options: ["tidak ada perbedaan, keduanya sama","topografi menggambarkan relief secara detail pada daerah kecil, korografi menggambarkan relief umum wilayah luas","topografi memakai warna, korografi hitam putih","topografi untuk pelayaran, korografi untuk penerbangan"], answer: 1, solution: "1. Topografi menampilkan relief detail (garis kontur) daerah relatif kecil. 2. Korografi menampilkan gambaran umum permukaan bumi wilayah luas. 3. Jadi perbedaannya pada tingkat detail dan cakupan wilayah." },
  { q: "Berikut ini yang termasuk peta tematik adalah ...", options: ["peta kadaster","peta persebaran jenis tanah","peta korografi","peta topografi"], answer: 1, solution: "1. Peta tematik menampilkan satu tema tertentu. 2. Persebaran jenis tanah adalah satu tema khusus. 3. Topografi, korografi, dan kadaster termasuk peta umum. Jadi jawabannya peta persebaran jenis tanah." },
  { q: "Peta yang menggambarkan seluruh permukaan bumi secara umum dengan skala sangat kecil disebut peta ...", options: ["tematik","kadaster","topografi","korografi"], answer: 3, solution: "1. Korografi menggambarkan relief umum wilayah luas. 2. Biasanya berskala kecil, misalnya peta dunia di atlas. 3. Jadi jawabannya korografi." },
  { q: "Peta geologi yang menunjukkan sebaran jenis batuan termasuk jenis peta ...", options: ["peta umum statis","peta khusus (tematik) statis","peta umum dinamis","peta khusus (tematik) dinamis"], answer: 1, solution: "1. Peta geologi menampilkan satu tema: sebaran batuan. 2. Sebaran batuan tidak berubah dalam waktu singkat, jadi bersifat statis. 3. Jadi termasuk peta khusus (tematik) statis." },
  { q: "Inset pada peta berfungsi untuk ...", options: ["menunjukkan arah utara","menjelaskan arti simbol","memperjelas daerah penting yang digambarkan dalam bingkai tersendiri","menunjukkan skala peta"], answer: 2, solution: "1. Inset adalah peta kecil penyisip di dalam peta utama. 2. Fungsinya memperbesar atau memperjelas daerah penting atau strategis. 3. Jadi jawabannya memperjelas daerah penting dalam bingkai tersendiri." },
  { q: "Fungsi lettering pada peta adalah ...", options: ["menunjukkan garis lintang dan bujur","penulisan huruf dan angka untuk mempertegas objek pada peta","menggambarkan relief permukaan bumi","membatasi tepi peta"], answer: 1, solution: "1. Lettering adalah tata cara penulisan pada peta. 2. Nama kota, sungai, dan gunung ditulis dengan aturan tertentu agar objeknya jelas. 3. Jadi fungsinya penulisan huruf untuk mempertegas objek." },
  { q: "Garis astronomis (garis lintang dan garis bujur) pada peta berfungsi untuk ...", options: ["menggambarkan bentuk relief","menunjukkan ketinggian tempat","menentukan arah mata angin","menentukan lokasi mutlak suatu tempat di permukaan bumi"], answer: 3, solution: "1. Garis lintang dan bujur membentuk sistem koordinat geografis. 2. Perpotongan keduanya menunjukkan lokasi mutlak (absolut). 3. Jadi jawabannya menentukan lokasi mutlak suatu tempat." },
  { q: "Fungsi tepi peta (neatline) adalah ...", options: ["menunjukkan skala peta","membatasi gambar peta dengan area di luarnya","menjelaskan simbol-simbol peta","menunjukkan judul peta"], answer: 1, solution: "1. Tepi peta adalah garis bingkai terluar peta. 2. Fungsinya memisahkan dan membatasi area peta dari area di luarnya. 3. Jadi jawabannya membatasi gambar peta." },
  { q: "Unsur peta yang menunjukkan arah mata angin disebut ...", options: ["orientasi","lettering","legenda","inset"], answer: 0, solution: "1. Setiap peta perlu penunjuk arah agar pembaca tahu orientasinya. 2. Unsur ini disebut orientasi, biasanya berupa tanda panah utara. 3. Jadi jawabannya orientasi." },
  { q: "Garis bujur 0 derajat (Greenwich) dan garis lintang 0 derajat (ekuator) pada peta termasuk komponen ...", options: ["lettering","inset","tepi peta","garis astronomis"], answer: 3, solution: "1. Greenwich dan ekuator adalah garis bujur dan garis lintang acuan. 2. Garis-garis lintang dan bujur disebut garis astronomis. 3. Jadi jawabannya garis astronomis." },
  { q: "Pada peta berskala 1:63.360, jarak 1 inci pada peta mewakili jarak sebenarnya ...", options: ["63.360 kilometer","1 kaki","1 kilometer","1 mil"], answer: 3, solution: "1. Diketahui 1 mil sama dengan 63.360 inci. 2. Skala 1:63.360 berarti 1 satuan pada peta sama dengan 63.360 satuan sebenarnya. 3. Jadi 1 inci sama dengan 63.360 inci, yaitu 1 mil." },
  { q: "Sebuah peta berskala 1:50.000 diperbesar dengan mesin fotokopi sebesar 2 kali (200 persen). Skala peta hasil perbesaran adalah ...", options: ["1:25.000","1:100.000","1:12.500","1:50.000"], answer: 0, solution: "1. Diperbesar 2 kali berarti setiap jarak pada peta menjadi 2 kali lipat. 2. Jarak sebenarnya tetap, sehingga skala menjadi 2 kali lebih besar. 3. Penyebut dibagi 2: 50.000 dibagi 2 sama dengan 25.000. Jadi jawabannya 1:25.000." },
  { q: "Peta berskala 1:100.000 diperkecil menjadi 50 persen dari ukuran semula. Skala peta yang baru adalah ...", options: ["1:150.000","1:50.000","1:200.000","1:100.000"], answer: 2, solution: "1. Diperkecil 50 persen berarti jarak pada peta menjadi setengahnya. 2. Skala menjadi setengahnya, sehingga penyebut dikali 2. 3. 100.000 dikali 2 sama dengan 200.000, jadi jawabannya 1:200.000." },
  { q: "Pada peta tertera skala garis: ruas sepanjang 5 cm mewakili 10 km. Skala angka peta tersebut adalah ...", options: ["1:500.000","1:20.000","1:200.000","1:2.000.000"], answer: 2, solution: "1. Ubah 10 km menjadi cm: 10 km sama dengan 1.000.000 cm. 2. Perbandingan 5 cm berbanding 1.000.000 cm sama dengan 1 berbanding 200.000. 3. Jadi skala angkanya 1:200.000." },
  { q: "Jarak sebenarnya antara dua kota adalah 45 km. Pada peta berskala 1:1.500.000, jarak kedua kota pada peta adalah ...", options: ["4,5 cm","30 cm","3 cm","6,75 cm"], answer: 2, solution: "1. Ubah 45 km menjadi cm: 45 km sama dengan 4.500.000 cm. 2. Jarak pada peta sama dengan 4.500.000 dibagi 1.500.000 sama dengan 3 cm. 3. Jadi jawabannya 3 cm." },
  { q: "Diketahui jarak fokus kamera (f) 152 mm dan tinggi terbang pesawat (H) 3.040 m. Skala foto udara yang dihasilkan adalah ...", options: ["1:20.000","1:2.000","1:30.400","1:200.000"], answer: 0, solution: "1. Rumus skala foto udara adalah f dibagi H. 2. Samakan satuan: 152 mm sama dengan 0,152 m, lalu 3.040 dibagi 0,152 sama dengan 20.000. 3. Jadi skalanya 1:20.000." },
  { q: "Peta A berskala 1:25.000 dan peta B berskala 1:250.000 menggambarkan daerah yang sama. Pernyataan yang benar adalah ...", options: ["peta A lebih detail karena penyebut skalanya lebih kecil","peta B mencakup wilayah lebih sempit","keduanya sama detailnya","peta B lebih detail karena angkanya lebih besar"], answer: 0, solution: "1. Makin kecil penyebut skala, makin besar dan detail petanya. 2. Nilai 25.000 lebih kecil dari 250.000, jadi peta A lebih detail. 3. Peta B justru mencakup wilayah lebih luas. Jadi jawabannya peta A lebih detail." },
  { q: "Simbol titik pada peta umumnya digunakan untuk menggambarkan ...", options: ["hutan dan perkebunan","jalan raya dan sungai","kota, gunung, dan bandara","danau dan waduk"], answer: 2, solution: "1. Simbol titik dipakai untuk objek berdimensi titik (lokasi). 2. Contohnya kota, puncak gunung, bandara, dan ibu kota. 3. Jalan dan sungai memakai simbol garis, danau dan hutan memakai simbol area. Jadi jawabannya kota, gunung, dan bandara." },
  { q: "Batas administrasi provinsi dan jalur rel kereta api pada peta digambarkan dengan simbol ...", options: ["titik","area","piktorial","garis"], answer: 3, solution: "1. Objek yang memanjang digambarkan dengan simbol garis. 2. Batas wilayah, jalan, sungai, dan rel termasuk objek memanjang. 3. Jadi jawabannya simbol garis." },
  { q: "Sawah, danau, dan kawasan hutan pada peta digambarkan dengan simbol ...", options: ["garis","panah","area (poligon)","titik"], answer: 2, solution: "1. Objek yang memiliki luasan digambarkan dengan simbol area. 2. Sawah, danau, dan hutan memiliki luasan yang jelas. 3. Jadi jawabannya simbol area (poligon)." },
  { q: "Dalam interpretasi citra, rona adalah ...", options: ["ukuran relatif antarobjek","susunan keruangan objek","tingkat kecerahan atau kegelapan objek pada citra","bentuk luar objek pada citra"], answer: 2, solution: "1. Rona adalah tingkat kecerahan atau kegelapan (tone) objek. 2. Rona ditentukan oleh daya pantul objek terhadap sensor. 3. Jadi jawabannya tingkat kecerahan atau kegelapan objek." },
  { q: "Pada citra inframerah, vegetasi yang sehat tampak berwarna merah terang. Hal ini terjadi karena ...", options: ["klorofil daun berwarna merah","daun memantulkan gelombang inframerah dengan kuat","tanah di bawahnya berwarna merah","daun menyerap seluruh gelombang inframerah"], answer: 1, solution: "1. Citra inframerah semu menonjolkan pantulan inframerah dekat. 2. Vegetasi sehat memantulkan inframerah sangat kuat sehingga tampil merah. 3. Jadi jawabannya karena daun memantulkan gelombang inframerah dengan kuat." },
  { q: "Unsur interpretasi citra yang menunjukkan susunan keruangan objek, misalnya permukiman memanjang mengikuti jalan, disebut ...", options: ["tekstur","bentuk","pola","ukuran"], answer: 2, solution: "1. Pola adalah ciri susunan keruangan objek pada citra. 2. Contohnya permukiman linier mengikuti jalan atau sungai dan pola aliran sungai. 3. Jadi jawabannya pola." },
  { q: "Tekstur kasar pada citra penginderaan jauh biasanya menunjukkan objek berupa ...", options: ["permukaan air danau","lapangan rumput","sawah yang rata","hutan dengan tajuk pohon tidak seragam"], answer: 3, solution: "1. Tekstur adalah frekuensi perubahan rona pada citra. 2. Tajuk pohon yang tidak seragam menimbulkan rona belang-belang sehingga tekstur kasar. 3. Sawah, air, dan lapangan yang rata bertekstur halus. Jadi jawabannya hutan." },
  { q: "Bayangan pada citra penginderaan jauh dapat dimanfaatkan untuk ...", options: ["mengukur suhu permukaan","menentukan jenis tanah","menentukan arah utara","menaksir tinggi objek seperti gedung atau tebing"], answer: 3, solution: "1. Panjang bayangan sebanding dengan tinggi objek dan sudut datang matahari. 2. Dari panjang bayangan dapat ditaksir tinggi gedung, pohon, atau tebing. 3. Jadi jawabannya menaksir tinggi objek." },
  { q: "Deretan perahu nelayan di sekitar suatu objek pada citra menjadi petunjuk bahwa objek tersebut adalah pelabuhan. Unsur interpretasi yang digunakan adalah ...", options: ["asosiasi","situs","konvergensi bukti","ketinggian"], answer: 0, solution: "1. Asosiasi adalah keterkaitan antara suatu objek dengan objek lain di sekitarnya. 2. Perahu nelayan berasosiasi dengan pelabuhan. 3. Jadi jawabannya asosiasi." },
  { q: "Konvergensi bukti dalam interpretasi citra berarti ...", options: ["membandingkan citra dari tahun yang berbeda","hanya memakai citra resolusi tertinggi","menggunakan satu unsur interpretasi yang paling jelas","memadukan beberapa unsur interpretasi untuk mengenali objek secara yakin"], answer: 3, solution: "1. Satu unsur interpretasi kadang belum cukup meyakinkan. 2. Konvergensi bukti menggabungkan beberapa unsur (rona, bentuk, pola, situs, asosiasi) hingga identifikasi objek mantap. 3. Jadi jawabannya memadukan beberapa unsur interpretasi." },
  { q: "Resolusi spasial suatu citra menunjukkan ...", options: ["jumlah saluran spektrum yang direkam sensor","selang waktu perekaman ulang suatu daerah","ukuran objek terkecil di permukaan bumi yang masih dapat dikenali","kepekaan sensor terhadap perbedaan kecerahan"], answer: 2, solution: "1. Resolusi spasial berkaitan dengan detail keruangan citra. 2. Makin kecil nilainya (misal 0,6 m), makin kecil objek yang masih dikenali. 3. Jadi jawabannya ukuran objek terkecil yang masih dapat dikenali." },
  { q: "Perbedaan sensor pasif dan sensor aktif pada penginderaan jauh adalah ...", options: ["sensor pasif menghasilkan citra foto, sensor aktif citra nonfoto","sensor pasif memakai tenaga matahari, sensor aktif memancarkan tenaga sendiri","sensor pasif lebih modern daripada sensor aktif","sensor pasif dipasang di satelit, sensor aktif di pesawat"], answer: 1, solution: "1. Sensor pasif merekam pantulan tenaga matahari, contohnya kamera dan Landsat. 2. Sensor aktif memancarkan gelombang sendiri lalu merekam pantulannya, contohnya RADAR dan LiDAR. 3. Jadi perbedaannya terletak pada sumber tenaganya." },
  { q: "Berikut ini yang termasuk sensor aktif adalah ...", options: ["kamera udara dan Landsat","SPOT dan IKONOS","RADAR dan LiDAR","film inframerah"], answer: 2, solution: "1. Sensor aktif memancarkan energi sendiri. 2. RADAR memancarkan gelombang mikro dan LiDAR memancarkan pulsa laser. 3. Kamera, Landsat, SPOT, dan IKONOS memakai tenaga matahari sehingga pasif. Jadi jawabannya RADAR dan LiDAR." },
  { q: "Satelit Landsat (Amerika Serikat) memiliki keunggulan utama berupa ...", options: ["liputan multitemporal yang konsisten sejak 1972 untuk memantau perubahan","hanya merekam pada malam hari","dapat menembus awan tebal","resolusi spasial sangat tinggi hingga 0,6 meter"], answer: 0, solution: "1. Landsat meluncur sejak 1972 dengan arsip citra yang berkesinambungan. 2. Keunggulannya adalah data runtut waktu untuk memantau perubahan lahan, deforestasi, dan perluasan kota. 3. Resolusi 0,6 m milik QuickBird, sedangkan yang menembus awan adalah RADAR. Jadi jawabannya liputan multitemporal sejak 1972." },
  { q: "Keunggulan wahana pesawat terbang dibandingkan satelit dalam penginderaan jauh adalah ...", options: ["tidak memerlukan awak","mencakup wilayah lebih luas","dapat terbang di bawah awan sehingga menghasilkan foto udara beresolusi sangat tinggi","periode perekaman lebih teratur"], answer: 2, solution: "1. Pesawat terbang rendah, di bawah lapisan awan. 2. Hasilnya foto udara beresolusi spasial sangat tinggi dan detail. 3. Satelit justru mencakup wilayah lebih luas dan tanpa awak. Jadi jawabannya dapat terbang di bawah awan." },
  { q: "Manfaat penginderaan jauh di bidang geologi adalah ...", options: ["memetakan arus lalu lintas","memantau pertumbuhan tanaman padi","mendeteksi struktur batuan untuk eksplorasi mineral dan minyak bumi","menghitung jumlah penduduk"], answer: 2, solution: "1. Citra dapat menampilkan kelurusan (lineament) dan struktur geologi. 2. Struktur tersebut menjadi petunjuk lokasi cebakan mineral dan minyak bumi. 3. Jadi jawabannya mendeteksi struktur batuan untuk eksplorasi." },
  { q: "Di bidang kehutanan, penginderaan jauh dimanfaatkan untuk ...", options: ["memantau luas hutan dan laju deforestasi","menghitung jumlah pohon satu per satu","menentukan harga kayu di pasar","menanam kembali hutan gundul"], answer: 0, solution: "1. Citra satelit multitemporal merekam tutupan lahan dari waktu ke waktu. 2. Perubahan tutupan hutan menjadi non-hutan menunjukkan deforestasi. 3. Jadi jawabannya memantau luas hutan dan laju deforestasi." },
  { q: "Salah satu kelemahan penginderaan jauh sistem pasif adalah ...", options: ["hasilnya tidak dapat diolah dengan komputer","terhalang oleh tutupan awan tebal","tidak dapat memetakan wilayah luas","datanya sulit diperoleh"], answer: 1, solution: "1. Sensor pasif mengandalkan pantulan cahaya matahari. 2. Awan tebal memantulkan cahaya sebelum mencapai permukaan sehingga objek tertutup. 3. Jadi jawabannya terhalang tutupan awan tebal." },
  { q: "Kelebihan penginderaan jauh dibandingkan survei lapangan adalah ...", options: ["dapat merekam wilayah luas dalam waktu singkat dan berulang (multitemporal)","biayanya selalu lebih murah","hasilnya selalu bebas dari awan","tidak memerlukan keahlian khusus"], answer: 0, solution: "1. Satu lembar citra satelit mencakup ratusan kilometer persegi. 2. Perekaman berulang memungkinkan pemantauan perubahan dari waktu ke waktu. 3. Survei lapangan butuh waktu lama untuk wilayah seluas itu. Jadi jawabannya merekam wilayah luas secara cepat dan berulang." },
  { q: "Dalam mitigasi bencana banjir, penginderaan jauh berperan untuk ...", options: ["mengevakuasi korban banjir","menghentikan aliran air banjir","membangun tanggul penahan banjir","memetakan sebaran genangan banjir dan daerah rawan banjir"], answer: 3, solution: "1. Citra satelit merekam sebaran genangan saat banjir terjadi. 2. Data ini dikombinasikan dengan data ketinggian menjadi peta rawan banjir. 3. PJ bersifat informatif (pemetaan), bukan aksi fisik. Jadi jawabannya memetakan genangan dan daerah rawan banjir." },
  { q: "Komponen SIG yang terdiri dari perangkat keras komputer, GPS, dan plotter disebut ...", options: ["software","hardware","brainware","data"], answer: 1, solution: "1. Perangkat keras adalah semua peralatan fisik dalam sistem. 2. Komputer, GPS, digitizer, dan plotter termasuk perangkat keras. 3. Dalam istilah SIG disebut hardware." },
  { q: "Brainware dalam SIG berperan sebagai ...", options: ["perangkat lunak pengolah data","metode analisis keruangan","sumber daya manusia pengelola dan pengguna sistem","data spasial dan atribut"], answer: 2, solution: "1. Brainware adalah manusia di balik sistem. 2. Operator, analis, dan pengambil keputusan yang mengoperasikan SIG. 3. Jadi jawabannya sumber daya manusia." },
  { q: "Analisis SIG yang dilakukan dengan menumpangsusunkan dua peta atau lebih untuk menghasilkan informasi baru disebut ...", options: ["network analysis","overlay","buffering","skoring"], answer: 1, solution: "1. Overlay adalah teknik tumpangsusun peta digital. 2. Contohnya peta jenis tanah ditumpuk dengan peta curah hujan dan peta lereng menjadi peta kesesuaian lahan. 3. Jadi jawabannya overlay." },
  { q: "Untuk menentukan zona larangan membangun dalam radius 100 meter di kiri-kanan sungai, analisis SIG yang tepat adalah ...", options: ["buffering","3D analysis","overlay","skoring"], answer: 0, solution: "1. Buffering membuat zona penyangga pada jarak tertentu dari suatu objek. 2. Radius 100 m di sekitar sungai adalah buffer sungai 100 m. 3. Jadi jawabannya buffering." },
  { q: "Analisis skoring (pengharkatan) dalam SIG digunakan untuk ...", options: ["menghitung jarak terdekat antarobjek","menampilkan relief tiga dimensi","memberi nilai pada tiap parameter lalu menjumlahkannya untuk klasifikasi","menganalisis jaringan jalan tercepat"], answer: 2, solution: "1. Skoring adalah pemberian harkat (nilai) pada setiap parameter. 2. Nilai-nilai dijumlahkan atau dibobotkan untuk menghasilkan kelas, misalnya tingkat kerawanan longsor. 3. Jadi jawabannya memberi nilai lalu menjumlahkannya." },
  { q: "Perbedaan data vektor dan data raster dalam SIG adalah ...", options: ["vektor berupa piksel, raster berupa titik garis poligon","vektor memakai titik garis poligon, raster memakai sel piksel atau grid","vektor untuk citra satelit, raster untuk peta administrasi","tidak ada perbedaan, keduanya sama"], answer: 1, solution: "1. Data vektor merepresentasikan objek sebagai titik, garis, dan poligon. 2. Data raster merepresentasikan objek sebagai sel-sel piksel (grid), misalnya citra satelit. 3. Jadi jawabannya vektor memakai titik-garis-poligon, raster memakai piksel." },
  { q: "Contoh penerapan SIG dalam perencanaan tata ruang kota adalah ...", options: ["memotret udara kawasan kota","menentukan lokasi ideal tempat pembuangan akhir sampah dengan overlay beberapa peta","menghitung jumlah penduduk kota","membangun gedung bertingkat"], answer: 1, solution: "1. SIG mengintegrasikan peta guna lahan, jarak ke permukiman, geologi, dan akses jalan. 2. Melalui overlay dan skoring diperoleh lokasi TPA yang paling sesuai. 3. Jadi jawabannya menentukan lokasi ideal TPA dengan overlay." },
  { q: "Untuk menentukan rute evakuasi tercepat dari kawasan rawan tsunami menuju tempat pengungsian, analisis SIG yang digunakan adalah ...", options: ["buffering","skoring","overlay","network analysis"], answer: 3, solution: "1. Rute tercepat dihitung berdasarkan jaringan jalan yang ada. 2. Analisis jaringan jalan dalam SIG disebut network analysis. 3. Jadi jawabannya network analysis." },
  { q: "Batas lempeng tempat dua lempeng saling bergeser berlawanan arah secara horizontal, contohnya Sesar San Andreas, disebut batas ...", options: ["subduksi","transform","konvergen","divergen"], answer: 1, solution: "1. Batas transform adalah batas tempat lempeng bergeser horizontal berlawanan arah. 2. Pada batas ini tidak terbentuk maupun hancur kerak bumi. 3. Contoh klasiknya Sesar San Andreas di California. Jadi jawabannya transform." },
  { q: "Palung Jawa (Sunda Trench) terbentuk akibat ...", options: ["dua lempeng saling menjauhi","dua lempeng bergeser mendatar","peregangan kerak benua","penunjaman Lempeng Indo-Australia ke bawah Lempeng Eurasia"], answer: 3, solution: "1. Palung Jawa adalah zona subduksi di selatan Sumatra-Jawa. 2. Lempeng Indo-Australia menunjam ke bawah Lempeng Eurasia. 3. Penunjaman adalah batas konvergen. Jadi jawabannya penunjaman Indo-Australia ke bawah Eurasia." },
  { q: "Menurut teori tektonik lempeng, lempeng-lempeng litosfer bergerak karena ...", options: ["hembusan angin muson","rotasi bumi","arus konveksi di astenosfer","gravitasi bulan"], answer: 2, solution: "1. Astenosfer bersifat plastis dan bersuhu tinggi. 2. Arus konveksi material mantel menyeret lempeng-lempeng di atasnya. 3. Inilah tenaga penggerak yang tidak mampu dijelaskan oleh Wegener. Jadi jawabannya arus konveksi di astenosfer." },
  { q: "Palung Mariana, palung terdalam di dunia, terbentuk pada zona ...", options: ["subduksi Lempeng Pasifik di bawah Lempeng Filipina","pemekaran lantai samudra","sesar mendatar","peregangan benua (rifting)"], answer: 0, solution: "1. Palung Mariana terletak di Pasifik bagian barat. 2. Terbentuk karena Lempeng Pasifik menunjam di bawah Lempeng Filipina. 3. Zona penunjaman disebut zona subduksi (konvergen). Jadi jawabannya subduksi Pasifik di bawah Filipina." },
  { q: "Gerakan konvergen antara lempeng benua dan lempeng benua menghasilkan ...", options: ["pegunungan lipatan tinggi seperti Himalaya","palung laut dalam","punggung tengah samudra","lembah rift"], answer: 0, solution: "1. Kedua lempeng benua sama-sama ringan sehingga tidak ada yang menunjam. 2. Keduanya terangkat dan terlipat ke atas. 3. Contohnya Himalaya dari tumbukan Lempeng India dan Eurasia. Jadi jawabannya pegunungan lipatan tinggi." },
  { q: "Bukti teori apungan benua Wegener berupa kesamaan fosil adalah ...", options: ["fosil trilobit di semua benua","fosil reptil Mesosaurus di Brasil dan Afrika Selatan","fosil mammoth di Siberia dan Alaska","fosil dinosaurus T-rex di Asia dan Eropa"], answer: 1, solution: "1. Mesosaurus adalah reptil air tawar yang tidak mampu menyeberangi samudra luas. 2. Fosilnya ditemukan di Brasil dan Afrika Selatan yang kini terpisah Samudra Atlantik. 3. Ini bukti kedua benua pernah menyatu. Jadi jawabannya fosil Mesosaurus." },
  { q: "Selain kesamaan garis pantai, bukti teori Wegener dari bidang klimatologi adalah ...", options: ["angin muson di Asia Selatan","ditemukannya lapisan batu bara di Antarktika yang kini beriklim dingin","adanya gurun pasir di Arab Saudi","curah hujan tinggi di Indonesia"], answer: 1, solution: "1. Batu bara terbentuk dari tumbuhan daerah tropis. 2. Lapisan batu bara ditemukan di Antarktika yang sekarang membeku. 3. Artinya Antarktika dahulu beriklim tropis sehingga posisinya pernah berbeda. Jadi jawabannya batu bara di Antarktika." },
  { q: "Kelemahan teori apungan benua Wegener menurut para ahli pada masanya adalah ...", options: ["Wegener tidak dapat menjelaskan tenaga penggerak pergeseran benua","tidak dapat menjelaskan gempa bumi","tidak didukung bukti fosil","bertentangan dengan bentuk garis pantai"], answer: 0, solution: "1. Wegener mengajukan benua bergerak dengan didukung bukti fosil dan batuan. 2. Namun ia tidak mampu menjelaskan gaya apa yang menggerakkan benua. 3. Baru terjawab setelah teori tektonik lempeng menemukan arus konveksi. Jadi jawabannya tidak dapat menjelaskan tenaga penggerak." },
  { q: "Kaldera raksasa seperti Danau Toba terbentuk akibat ...", options: ["penurunan muka air danau","letusan efusif lava encer","letusan eksplosif sangat kuat yang meruntuhkan puncak gunung","erosi kawah oleh air hujan"], answer: 2, solution: "1. Kaldera adalah kawah raksasa berdiameter belasan kilometer. 2. Terbentuk saat letusan dahsyat mengosongkan dapur magma sehingga puncak gunung runtuh. 3. Danau Toba terbentuk dari letusan supervulkan sekitar 74.000 tahun lalu. Jadi jawabannya letusan eksplosif sangat kuat." },
  { q: "Gunung Lamongan di Jawa Timur merupakan contoh gunung api maar karena ...", options: ["terbentuk dari satu kali letusan eksplosif kuat membentuk kawah lebar yang terisi danau","memiliki kubah lava di puncaknya","tersusun dari lapisan lava dan piroklastik","terbentuk dari letusan efusif lava encer"], answer: 0, solution: "1. Maar adalah kawah ledakan dari letusan eksplosif tunggal yang kuat. 2. Kawahnya lebar dan dangkal, sering terisi air menjadi danau (ranu). 3. Gunung Lamongan memiliki danau kawah. Jadi jawabannya kawah lebar berisi danau." },
  { q: "Menurut klasifikasi PVMBG, gunung api yang tidak tercatat pernah meletus tetapi masih menunjukkan aktivitas solfatar atau fumarol digolongkan tipe ...", options: ["tipe B","tipe C","tipe A","tipe D"], answer: 1, solution: "1. Tipe A adalah gunung api yang pernah meletus sejak tahun 1600. 2. Tipe B pernah meletus sebelum tahun 1600. 3. Tipe C tidak ada catatan letusan tetapi masih bergejala solfatar atau fumarol. Jadi jawabannya tipe C." },
  { q: "Ciri gunung api strato yang membedakannya dari gunung api perisai adalah ...", options: ["lava lebih kental dan letusannya lebih eksplosif","lereng lebih landai","tidak menghasilkan abu vulkanik","lava lebih encer"], answer: 0, solution: "1. Gunung strato bermagma andesitis yang kental sehingga gas sulit keluar dan letusannya eksplosif. 2. Gunung perisai bermagma basaltis encer sehingga efusif dengan lereng landai. 3. Jadi pembedanya adalah lava lebih kental dan letusan lebih eksplosif." },
  { q: "Tipe letusan Hawaii bercirikan ...", options: ["lontaran bom vulkanik ritmis tiap beberapa menit","ledakan sangat kuat menghancurkan puncak gunung","lelehan lava encer yang mengalir tenang tanpa ledakan berarti","awan panas yang meluncur cepat"], answer: 2, solution: "1. Magma basaltis sangat encer sehingga gas mudah lepas. 2. Letusannya bersifat efusif, yaitu lava meleleh dan mengalir. 3. Contohnya Kilauea dan Mauna Loa. Jadi jawabannya lelehan lava encer yang mengalir tenang." },
  { q: "Letusan tipe Stromboli bercirikan ...", options: ["awan panas guguran dari kubah lava","lava mengalir tenang tanpa ledakan","gas bertekanan tinggi menghancurkan sisi gunung","ledakan-ledakan kecil yang terjadi terus-menerus secara ritmis"], answer: 3, solution: "1. Magmanya agak kental sehingga gas terkumpul lalu meledak kecil. 2. Ledakan terjadi berulang seperti kembang api yang ritmis. 3. Contohnya Gunung Stromboli di Italia. Jadi jawabannya ledakan kecil yang ritmis." },
  { q: "Awan panas (wedhus gembel) yang meluncur dari runtuhnya kubah lava merupakan ciri letusan tipe ...", options: ["Hawaii","Stromboli","Vulkano","Merapi"], answer: 3, solution: "1. Pada tipe Merapi, magma kental membentuk kubah lava di kawah. 2. Kubah yang tidak kuat menahan tekanan runtuh menjadi awan panas guguran. 3. Inilah wedhus gembel khas Gunung Merapi. Jadi jawabannya tipe Merapi." },
  { q: "Letusan tipe Pelee terkenal karena ...", options: ["tidak menimbulkan korban jiwa","lava encer mengalir jauh","awan panas bertekanan gas sangat tinggi yang menghancurkan Kota St. Pierre tahun 1902","ledakan kecil yang ritmis"], answer: 2, solution: "1. Gunung Pelee di Martinique meletus dahsyat tahun 1902. 2. Awan panas (nuee ardente) meluncur cepat dan menghancurkan Kota St. Pierre dengan puluhan ribu korban. 3. Gas bertekanan tinggi adalah ciri tipe Pelee. Jadi jawabannya awan panas yang menghancurkan St. Pierre." },
  { q: "Letusan tipe Perret merupakan letusan paling dahsyat karena ...", options: ["letusannya kecil dan ritmis","hanya mengeluarkan asap tipis","gas bertekanan sangat tinggi menghancurkan tubuh gunung dan abu mencapai stratosfer","lava encer mengalir tenang"], answer: 2, solution: "1. Pada tipe Perret, gas bertekanan luar biasa kuat. 2. Ledakannya menghancurkan tubuh gunung dan melontarkan abu hingga stratosfer. 3. Contohnya letusan Krakatau 1883 dan Tambora 1815. Jadi jawabannya gas bertekanan sangat tinggi." },
  { q: "Urutan material eflata dari yang berukuran paling besar ke paling kecil adalah ...", options: ["abu - bom - lapili","lapili - bom - abu","abu - lapili - bom","bom - lapili - abu"], answer: 3, solution: "1. Bom vulkanik berdiameter lebih dari 64 mm, paling besar. 2. Lapili berdiameter 2 sampai 64 mm. 3. Abu vulkanik berdiameter kurang dari 2 mm, paling kecil. Jadi urutannya bom - lapili - abu." },
  { q: "Lahar dingin berbeda dengan lahar panas karena lahar dingin ...", options: ["berupa lava pijar yang mengalir saat letusan","bersuhu lebih dari 1000 derajat","hanya terjadi di puncak gunung","berupa campuran material vulkanik lepas dengan air hujan yang terjadi setelah letusan"], answer: 3, solution: "1. Lahar panas adalah aliran material panas saat atau sesaat setelah letusan. 2. Lahar dingin adalah endapan piroklastik yang terbawa air hujan dan bisa terjadi lama setelah letusan. 3. Lahar dingin sering menimbulkan banjir bandang. Jadi jawabannya campuran material dengan air hujan setelah letusan." },
  { q: "Gas vulkanik yang berupa uap air disebut ...", options: ["fumarol","belerang","mofet","solfatar"], answer: 0, solution: "1. Fumarol adalah ekshalasi gunung api berupa uap air. 2. Solfatar mengeluarkan gas belerang, sedangkan mofet mengeluarkan gas CO2. 3. Jadi gas berupa uap air disebut fumarol." },
  { q: "Gas beracun yang keluar dari gunung api dan membahayakan penambang di sekitar kawah, misalnya di Kawah Ijen, adalah ...", options: ["nitrogen","hidrogen","belerang (solfatar)","oksigen"], answer: 2, solution: "1. Solfatar mengeluarkan gas belerang (H2S dan SO2) yang beracun. 2. Di Kawah Ijen, gas belerang menjadi bahaya utama bagi para penambang. 3. Jadi jawabannya belerang." },
  { q: "Material vulkanisme yang dimanfaatkan sebagai bahan bangunan ringan dan isolator adalah ...", options: ["batu apung (pumice)","bom vulkanik","lahar panas","gas mofet"], answer: 0, solution: "1. Batu apung berpori, ringan, bahkan dapat mengapung di air. 2. Dimanfaatkan sebagai bahan bangunan ringan, amplas, dan isolator. 3. Jadi jawabannya batu apung." },
  { q: "Berikut ini yang merupakan tanda-tanda gunung api akan meletus adalah ...", options: ["suhu kawah turun dan hewan naik ke puncak","gempa vulkanik meningkat, suhu kawah naik, dan hewan turun gunung","tumbuhan di lereng tumbuh subur","curah hujan meningkat tajam"], answer: 1, solution: "1. Magma yang naik menimbulkan gempa vulkanik dan menaikkan suhu kawah. 2. Hewan yang peka getaran turun ke kaki gunung, tumbuhan layu, dan mata air kering. 3. Jadi jawabannya gempa vulkanik meningkat, suhu naik, dan hewan turun gunung." },
  { q: "Manfaat vulkanisme bagi bidang pertanian adalah ...", options: ["abu vulkanik menyuburkan tanah","gas belerang membunuh gulma","awan panas mengairi sawah","lava menghancurkan hama tanaman"], answer: 0, solution: "1. Abu vulkanik kaya mineral seperti kalium dan fosfor. 2. Setelah melapuk menjadi tanah vulkanik yang sangat subur. 3. Contohnya lahan subur di lereng Merapi. Jadi jawabannya abu vulkanik menyuburkan tanah." },
  { q: "Batuan beku yang membeku di dalam gang atau korok magma sehingga kristalnya berukuran tidak seragam disebut batuan beku ...", options: ["sedimen klastis","luar (vulkanik)","gang (porfirik)","dalam (plutonik)"], answer: 2, solution: "1. Lokasi pembekuan magma menentukan jenis batuan beku. 2. Yang membeku di gang atau korok disebut batuan beku gang, contohnya porfiri. 3. Kristalnya campuran besar-kecil karena pendinginan dua tahap. Jadi jawabannya batuan beku gang." },
  { q: "Pasangan batuan beku luar (vulkanik) yang tepat adalah ...", options: ["gabro dan peridotit","andesit dan basal","porfiri dan granit","granit dan diorit"], answer: 1, solution: "1. Batuan beku luar membeku di permukaan sehingga kristalnya halus. 2. Contohnya andesit, basal, obsidian, dan batu apung. 3. Granit, diorit, dan gabro adalah beku dalam, sedangkan porfiri adalah beku gang. Jadi jawabannya andesit dan basal." },
  { q: "Obsidian (kaca vulkanik) terbentuk karena ...", options: ["lava membeku sangat cepat sehingga tidak sempat membentuk kristal","batuan sedimen mengalami tekanan tinggi","lava bercampur air laut","magma membeku perlahan di dalam bumi"], answer: 0, solution: "1. Lava yang sangat cepat dingin, misalnya saat masuk ke air. 2. Atom-atomnya tidak sempat menyusun kristal sehingga bertekstur kaca. 3. Jadi jawabannya membeku sangat cepat tanpa membentuk kristal." },
  { q: "Batu bara termasuk batuan sedimen organik karena ...", options: ["terbentuk dari penguapan air laut","terbentuk dari timbunan sisa tumbuhan yang membusuk","terbentuk dari pecahan batuan lain","terbentuk dari lelehan magma"], answer: 1, solution: "1. Sedimen organik berasal dari sisa makhluk hidup. 2. Batu bara berasal dari timbunan tumbuhan (gambut) yang tertekan selama jutaan tahun. 3. Jadi jawabannya dari sisa tumbuhan." },
  { q: "Gips termasuk batuan sedimen kimiawi karena terbentuk melalui ...", options: ["penguapan air laut yang meninggalkan endapan mineral","timbunan cangkang kerang","pembekuan lava","sementasi pecahan kerikil"], answer: 0, solution: "1. Sedimen kimiawi terbentuk melalui proses kimia, misalnya penguapan. 2. Air laut yang menguap meninggalkan endapan mineral seperti gips dan garam. 3. Jadi jawabannya penguapan air laut." },
  { q: "Perbedaan breksi dan konglomerat terletak pada ...", options: ["warna batuannya","tempat terbentuknya","breksi berbutir runcing, konglomerat berbutir membundar","kandungan mineralnya"], answer: 2, solution: "1. Keduanya adalah batuan sedimen klastis berbutir kasar. 2. Breksi berfragmen bersudut atau runcing karena belum jauh terangkut. 3. Konglomerat berfragmen membundar karena lama tererosi selama pengangkutan. Jadi jawabannya bentuk butir." },
  { q: "Marmer terbentuk dari batu gamping melalui metamorfosis ...", options: ["tidak termasuk metamorfosis","dinamo","regional","kontak (termal)"], answer: 3, solution: "1. Marmer adalah batu gamping yang telah termetamorfosis. 2. Perubahan terjadi akibat panas magma di sekitarnya. 3. Metamorfosis akibat panas disebut metamorfosis kontak (termal). Jadi jawabannya kontak." },
  { q: "Sabak (slate) berasal dari batuan ...", options: ["granit","batu gamping","batu pasir","serpih (shale)"], answer: 3, solution: "1. Sabak berfoliasi halus dan mudah dibelah tipis-tipis. 2. Berasal dari serpih (shale) yang mengalami tekanan. 3. Batu pasir menjadi kuarsit dan batu gamping menjadi marmer. Jadi jawabannya serpih." },
  { q: "Dalam siklus batuan, batuan metamorf dapat berubah kembali menjadi magma melalui tahapan ...", options: ["litifikasi dan sementasi","panas dan tekanan tinggi hingga meleleh","pendinginan lava","pelapukan - erosi - sedimentasi"], answer: 1, solution: "1. Siklus batuan berjalan: magma menjadi beku, menjadi sedimen, menjadi metamorf, kembali menjadi magma. 2. Batuan metamorf yang terus tertekan dan terpanas akan meleleh. 3. Lelehan itu menjadi magma sehingga siklus berulang. Jadi jawabannya panas dan tekanan tinggi hingga meleleh." },
  { q: "Berikut ini yang termasuk tenaga endogen adalah ...", options: ["tektonisme, vulkanisme, dan seisme","angin, air, dan gletser","pelapukan, erosi, dan sedimentasi","longsor dan rayapan"], answer: 0, solution: "1. Tenaga endogen berasal dari dalam bumi dan bersifat membangun. 2. Meliputi tektonisme (gerak lempeng), vulkanisme, dan seisme (gempa). 3. Pelapukan, erosi, dan sedimentasi adalah tenaga eksogen. Jadi jawabannya tektonisme, vulkanisme, dan seisme." },
  { q: "Retaknya batuan di gurun akibat perbedaan suhu siang dan malam yang ekstrem termasuk pelapukan ...", options: ["biologis oleh akar","organik","kimiawi","mekanik (fisik)"], answer: 3, solution: "1. Batuan memuai pada siang hari dan menyusut pada malam hari. 2. Berulang-ulang sehingga batuan retak tanpa perubahan kimia. 3. Pelapukan tanpa perubahan kimia disebut pelapukan mekanik (insolasi). Jadi jawabannya mekanik." },
  { q: "Contoh pelapukan kimiawi adalah ...", options: ["besi berkarat karena oksidasi","batuan pecah karena membekunya air","akar pohon menembus celah batuan","cacing menggemburkan tanah"], answer: 0, solution: "1. Pelapukan kimiawi mengubah komposisi mineral batuan. 2. Oksidasi membuat besi bereaksi dengan oksigen dan air menjadi karat sehingga batuan lapuk. 3. Akar dan cacing adalah pelapukan organik, sedangkan es adalah mekanik. Jadi jawabannya besi berkarat karena oksidasi." },
  { q: "Abrasi berbeda dengan deflasi karena abrasi ...", options: ["disebabkan gletser di pegunungan","disebabkan angin di gurun","disebabkan gelombang laut yang mengikis pantai","disebabkan aliran air sungai"], answer: 2, solution: "1. Abrasi adalah erosi oleh gelombang dan arus laut di pantai. 2. Deflasi adalah erosi oleh angin di gurun. 3. Erosi oleh sungai disebut ablasi dan oleh gletser disebut eksarasi. Jadi jawabannya gelombang laut mengikis pantai." },
  { q: "Dampak negatif erosi air (ablasi) bagi lahan pertanian adalah ...", options: ["tanah menjadi lebih subur","terbentuk delta yang subur","cadangan air tanah bertambah","lapisan tanah atas yang subur terkikis sehingga produktivitas menurun"], answer: 3, solution: "1. Air hujan dan limpasan permukaan mengangkut lapisan tanah atas. 2. Lapisan atas (topsoil) adalah yang paling subur, sehingga kehilangannya menurunkan produktivitas. 3. Jadi jawabannya lapisan tanah atas terkikis dan produktivitas menurun." },
  { q: "Sedimentasi fluvial yang membentuk dataran banjir dan delta terjadi karena ...", options: ["gelombang laut mengikis pantai","gletser mencair","angin mengendapkan pasir","kecepatan aliran sungai menurun sehingga material yang diangkut diendapkan"], answer: 3, solution: "1. Sungai mengangkut material saat berarus deras. 2. Saat arus melambat, misalnya di dataran rendah dan muara, daya angkutnya turun. 3. Material lalu diendapkan membentuk dataran banjir dan delta. Jadi jawabannya kecepatan aliran menurun." },
  { q: "Perbedaan longsor (landslide) dan rayapan (creep) adalah ...", options: ["longsor bergerak lambat, rayapan bergerak cepat","longsor hanya terjadi di gurun, rayapan di pegunungan","longsor adalah gerakan massa batuan atau tanah yang cepat, rayapan gerakannya sangat lambat","keduanya sama saja"], answer: 2, solution: "1. Keduanya termasuk gerakan massa (mass wasting). 2. Longsor terjadi cepat, tiba-tiba, dan merusak. 3. Rayapan sangat lambat (cm per tahun), terlihat dari tiang atau pohon yang miring. Jadi jawabannya longsor cepat, rayapan sangat lambat." },
  { q: "Pada lipatan, bagian yang melengkung ke atas (punggung lipatan) disebut ...", options: ["graben","antiklin","sinklin","horst"], answer: 1, solution: "1. Lipatan memiliki dua bagian utama: antiklin dan sinklin. 2. Antiklin adalah punggung lipatan yang melengkung ke atas. 3. Sinklin adalah lembah lipatan, sedangkan horst dan graben adalah hasil patahan. Jadi jawabannya antiklin." },
  { q: "Graben (slenk) terbentuk akibat ...", options: ["lipatan batuan","blok batuan yang turun di antara dua patahan","erosi sungai","letusan gunung api"], answer: 1, solution: "1. Pada patahan, horst adalah blok yang naik dan graben adalah blok yang turun. 2. Graben berupa lembah patahan di antara dua sesar. 3. Contohnya Lembah Rift di Afrika Timur. Jadi jawabannya blok batuan yang turun." },
  { q: "Sesar Semangko yang memanjang di Bukit Barisan Sumatra dan sering memicu gempa termasuk jenis sesar ...", options: ["naik (thrust fault)","mendatar (strike-slip fault)","bukan sesar","turun (normal fault)"], answer: 1, solution: "1. Sesar Semangko memanjang di sepanjang Bukit Barisan. 2. Pergerakan blok batuannya mendatar (horizontal). 3. Sesar dengan gerak mendatar disebut strike-slip fault. Jadi jawabannya mendatar." },
  { q: "Skala MMI (Modified Mercalli Intensity) mengukur gempa berdasarkan ...", options: ["tingkat kerusakan dan guncangan yang dirasakan manusia","energi yang dilepaskan di hiposentrum","kedalaman hiposentrum","kecepatan gelombang primer"], answer: 0, solution: "1. Magnitudo (Richter) mengukur energi yang dilepaskan di sumber gempa. 2. MMI mengukur dampak gempa: apa yang dirasakan manusia dan kerusakan bangunan, berskala I sampai XII. 3. Jadi jawabannya tingkat kerusakan dan guncangan yang dirasakan." },
  { q: "Gelombang gempa yang merambat paling cepat dan tercatat pertama oleh seismograf adalah gelombang ...", options: ["primer","sekunder","Rayleigh","permukaan (Love)"], answer: 0, solution: "1. Gelombang primer (P) adalah gelombang longitudinal yang paling cepat. 2. Gelombang sekunder (S) lebih lambat, sedangkan gelombang permukaan paling lambat tetapi paling merusak. 3. Jadi yang pertama tercatat seismograf adalah gelombang primer." },
  { q: "Gelombang sekunder (S) tidak dapat merambat melalui inti luar bumi yang cair karena ...", options: ["gelombang S diserap mantel","gelombang transversal hanya merambat melalui benda padat","gelombang S terlalu cepat","inti bumi terlalu panas"], answer: 1, solution: "1. Gelombang S adalah gelombang transversal, yaitu getarannya tegak lurus arah rambat. 2. Gelombang transversal hanya dapat merambat melalui medium padat, tidak melalui cairan. 3. Fakta ini menjadi bukti bahwa inti luar bumi bersifat cair. Jadi jawabannya hanya merambat melalui benda padat." },
  { q: "Tsunami umumnya dipicu oleh ...", options: ["gempa tektonik dangkal di bawah laut dengan pergeseran vertikal","gempa vulkanik di puncak gunung","gelombang pasang saat bulan purnama","angin topan di samudra"], answer: 0, solution: "1. Tsunami membutuhkan perpindahan massa air laut dalam jumlah besar. 2. Gempa megathrust dangkal mengangkat atau menurunkan dasar laut secara tiba-tiba. 3. Contohnya gempa Aceh 2004. Jadi jawabannya gempa tektonik dangkal bawah laut dengan pergeseran vertikal." },
  { q: "Upaya mitigasi tsunami yang paling tepat bagi masyarakat pesisir adalah ...", options: ["menangkap ikan saat air surut tiba-tiba","membangun rumah tepat di tepi pantai","menanam bakau, memasang sistem peringatan dini, dan menyiapkan jalur evakuasi ke dataran tinggi","menunggu hingga air laut surut"], answer: 2, solution: "1. Mitigasi adalah upaya mengurangi risiko sebelum bencana terjadi. 2. Sistem peringatan dini, jalur evakuasi, dan sabuk hijau bakau memperlambat gelombang. 3. Air surut tiba-tiba justru tanda tsunami sehingga harus segera mengungsi. Jadi jawabannya peringatan dini dan jalur evakuasi." },
{ q: "Air hujan yang tertahan oleh daun dan ranting pepohonan sebelum jatuh ke permukaan tanah disebut ...", options: ["intersepsi", "infiltrasi", "perkolasi", "evaporasi"], answer: 0, solution: "1. Intersepsi adalah tertahannya air hujan oleh tajuk tumbuhan sebelum mencapai tanah. 2. Infiltrasi adalah peresapan air ke dalam tanah, perkolasi adalah pergerakan air ke lapisan yang lebih dalam, sedangkan evaporasi adalah penguapan. 3. Jadi, jawaban yang benar adalah intersepsi." },
  { q: "Perbedaan infiltrasi dan perkolasi dalam siklus hidrologi adalah ...", options: ["infiltrasi terjadi di laut sedangkan perkolasi terjadi di darat", "infiltrasi adalah penguapan sedangkan perkolasi adalah pengembunan", "infiltrasi adalah peresapan air ke dalam tanah, sedangkan perkolasi adalah pergerakan air ke lapisan yang lebih dalam menuju air tanah", "keduanya sama, yaitu aliran air di permukaan tanah"], answer: 2, solution: "1. Infiltrasi adalah proses meresapnya air dari permukaan ke dalam tanah. 2. Perkolasi adalah lanjutan infiltrasi, yaitu pergerakan air secara vertikal ke lapisan yang lebih dalam sampai mencapai zona jenuh air tanah. 3. Jadi, jawaban yang benar adalah infiltrasi adalah peresapan air ke dalam tanah, sedangkan perkolasi adalah pergerakan air ke lapisan yang lebih dalam." },
  { q: "Limpasan air hujan yang mengalir di permukaan tanah menuju sungai karena tanah sudah jenuh air disebut ...", options: ["kondensasi", "adveksi", "intersepsi", "run off"], answer: 3, solution: "1. Run off (limpasan permukaan) adalah aliran air hujan di permukaan tanah yang tidak terserap. 2. Kondensasi adalah pengembunan uap air, adveksi adalah perpindahan massa udara horizontal, dan intersepsi adalah air yang tertahan tajuk tumbuhan. 3. Jadi, jawaban yang benar adalah run off." },
  { q: "Perubahan wujud uap air menjadi titik-titik air yang kemudian membentuk awan disebut ...", options: ["evaporasi", "kondensasi", "transpirasi", "sublimasi"], answer: 1, solution: "1. Kondensasi adalah perubahan uap air menjadi cairan karena pendinginan udara. 2. Titik-titik air hasil kondensasi berkumpul membentuk awan. 3. Jadi, jawaban yang benar adalah kondensasi." },
  { q: "Siklus hidrologi pendek (kecil) memiliki ciri ...", options: ["penguapan air laut, pembentukan awan, lalu hujan jatuh kembali ke laut tanpa melewati daratan", "penguapan air laut, hujan di pegunungan dekat pantai, lalu kembali ke laut melalui sungai", "penguapan air laut, hujan di pedalaman yang jauh dari pantai, lalu kembali melalui sungai-sungai panjang", "tidak melibatkan penguapan sama sekali"], answer: 0, solution: "1. Siklus pendek terjadi seluruhnya di atas laut: evaporasi, kondensasi, presipitasi kembali ke laut. 2. Siklus sedang melibatkan daratan dekat pantai, sedangkan siklus panjang melibatkan daratan pedalaman yang jauh. 3. Jadi, jawaban yang benar adalah penguapan air laut lalu hujan kembali ke laut tanpa melewati daratan." },
  { q: "Hujan yang jatuh di daerah pedalaman yang jauh dari laut, kemudian airnya mengalir melalui sungai-sungai dan akhirnya kembali ke laut merupakan contoh siklus hidrologi ...", options: ["pendek", "sedang", "panjang", "tertutup"], answer: 2, solution: "1. Siklus panjang menempuh perjalanan terjauh: laut - awan - hujan di pedalaman jauh - sungai - laut. 2. Siklus pendek hanya di atas laut, siklus sedang hanya sampai daratan dekat pantai. 3. Jadi, jawaban yang benar adalah panjang." },
  { q: "Batas alami suatu daerah aliran sungai (DAS) umumnya berupa ...", options: ["garis pantai", "punggung bukit atau igir pegunungan", "muara sungai", "danau di daerah hilir"], answer: 1, solution: "1. DAS adalah wilayah yang menampung dan mengalirkan air ke satu sungai utama. 2. Air hujan di kedua sisi punggung bukit mengalir ke DAS yang berbeda, sehingga punggung bukit menjadi pemisah alami antar-DAS. 3. Jadi, jawaban yang benar adalah punggung bukit atau igir pegunungan." },
  { q: "Pola aliran sungai trellis yang berbentuk seperti terali berkembang di daerah ...", options: ["berbatuan homogen", "berkubah yang terkikis", "berstruktur lipatan seperti antiklin dan sinklin", "kerucut gunung api"], answer: 2, solution: "1. Pola trellis memiliki anak sungai yang sejajar dan bermuara tegak lurus ke sungai utama seperti terali. 2. Pola ini terbentuk di daerah lipatan, dengan sungai utama mengikuti lembah sinklin dan anak sungai menuruni lereng antiklin. 3. Jadi, jawaban yang benar adalah berstruktur lipatan seperti antiklin dan sinklin." },
  { q: "Pola aliran sungai radial sentrifugal, yaitu anak-anak sungai mengalir menjauhi satu titik pusat ke segala arah, umumnya terbentuk di ...", options: ["daerah cekungan", "lereng yang curam", "kerucut gunung api", "daerah patahan"], answer: 2, solution: "1. Radial sentrifugal berarti aliran menyebar keluar dari pusat. 2. Bentuk kerucut gunung api membuat air hujan mengalir dari puncak ke segala arah lereng. 3. Jadi, jawaban yang benar adalah kerucut gunung api." },
  { q: "Di suatu daerah cekungan (depresi), anak-anak sungai mengalir dari segala arah menuju satu titik di tengah cekungan. Pola aliran tersebut disebut pola ...", options: ["dendritik", "trellis", "radial sentripetal", "rektangular"], answer: 2, solution: "1. Radial sentripetal berarti aliran menuju ke pusat dari segala arah. 2. Di daerah cekungan, air mengalir dari daerah yang lebih tinggi di sekelilingnya menuju titik terendah di tengah. 3. Jadi, jawaban yang benar adalah radial sentripetal." },
  { q: "Pola aliran rektangular yang alirannya membentuk sudut-sudut siku-siku berkembang di daerah ...", options: ["berstruktur patahan", "berbatuan homogen", "kubah yang terkikis", "lereng gunung api"], answer: 0, solution: "1. Pola rektangular memiliki belokan-belokan tegak lurus mengikuti garis patahan. 2. Air mengikuti zona-zona lemah berupa rekahan dan patahan batuan yang saling tegak lurus. 3. Jadi, jawaban yang benar adalah berstruktur patahan." },
  { q: "Pola aliran anular yang melingkar seperti cincin terbentuk di daerah ...", options: ["cekungan", "lipatan", "dataran banjir", "kubah (dome) yang telah terkikis"], answer: 3, solution: "1. Pola anular berupa lingkaran-lingkaran konsentris. 2. Pola ini terbentuk di kubah yang terkikis, dengan sungai-sungai mengikuti lapisan batuan yang tersingkap melingkar. 3. Jadi, jawaban yang benar adalah kubah (dome) yang telah terkikis." },
  { q: "Pola aliran paralel dengan anak-anak sungai yang mengalir sejajar satu sama lain umumnya terdapat di daerah ...", options: ["dataran rendah yang luas", "lereng yang curam", "cekungan", "kubah"], answer: 1, solution: "1. Pola paralel memiliki anak sungai yang sejajar mengikuti arah kemiringan lereng. 2. Pola ini umum di lereng yang curam dan seragam, misalnya lereng pegunungan muda. 3. Jadi, jawaban yang benar adalah lereng yang curam." },
  { q: "Sungai pada stadium dewasa memiliki ciri ...", options: ["lembah berbentuk V dan banyak air terjun", "dataran banjir sangat luas dan banyak delta", "aliran lurus dan deras di pegunungan", "aliran berkelok-kelok (meander) dengan lembah berbentuk U"], answer: 3, solution: "1. Stadium muda berciri lembah V dan air terjun karena erosi vertikal dominan. 2. Pada stadium dewasa, erosi lateral dominan sehingga lembah melebar berbentuk U dan aliran berkelok membentuk meander. 3. Jadi, jawaban yang benar adalah aliran berkelok-kelok (meander) dengan lembah berbentuk U." },
  { q: "Danau tapal kuda (oxbow lake) terbentuk karena ...", options: ["kelokan meander yang terpotong sehingga alirannya menjadi lurus dan kelokan lama menjadi danau", "letusan gunung api", "pelarutan batu gamping", "bendungan buatan manusia"], answer: 0, solution: "1. Pada stadium dewasa dan tua, kelokan meander semakin tajam karena erosi di sisi luar dan pengendapan di sisi dalam. 2. Saat banjir, aliran memotong leher kelokan sehingga alirannya lurus; kelokan yang terputus menjadi danau berbentuk tapal kuda. 3. Jadi, jawaban yang benar adalah kelokan meander yang terpotong." },
  { q: "Delta di muara sungai terbentuk karena ...", options: ["erosi air laut", "patahan kerak bumi", "pengendapan material yang dibawa sungai saat kecepatan aliran menurun di muara", "intrusi air laut"], answer: 2, solution: "1. Sungai stadium tua membawa banyak material hasil erosi. 2. Di muara, kecepatan aliran menurun drastis sehingga daya angkut hilang dan material diendapkan membentuk daratan baru berbentuk kipas. 3. Jadi, jawaban yang benar adalah pengendapan material saat kecepatan aliran menurun di muara." },
  { q: "Danau Kelimutu di Flores dan Danau Batur di Bali termasuk danau vulkanik karena terbentuk akibat ...", options: ["patahan kerak bumi", "letusan gunung api yang kawah atau kalderanya terisi air", "pelarutan batu gamping", "terpisahnya teluk oleh gosong pasir"], answer: 1, solution: "1. Danau vulkanik terbentuk oleh aktivitas vulkanisme. 2. Kawah atau kaldera bekas letusan yang terisi air hujan membentuk danau, seperti Danau Kelimutu dan Danau Batur. 3. Jadi, jawaban yang benar adalah letusan gunung api yang kawah atau kalderanya terisi air." },
  { q: "Danau-danau kecil di kawasan karst Gunung Kidul yang terbentuk akibat pelarutan batu gamping oleh air hujan disebut danau ...", options: ["tektonik", "vulkanik", "laguna", "karst atau dolina"], answer: 3, solution: "1. Air hujan yang sedikit asam melarutkan batu gamping di kawasan karst. 2. Cekungan hasil pelarutan yang terisi air disebut dolina, dan bila cukup besar disebut danau karst. 3. Jadi, jawaban yang benar adalah karst atau dolina." },
  { q: "Segara Anakan di Cilacap merupakan contoh danau laguna, yaitu danau yang terbentuk karena ...", options: ["aktivitas tektonik", "letusan gunung api", "bendungan sungai oleh manusia", "terpisahnya sebagian perairan laut oleh endapan pasir di pesisir"], answer: 3, solution: "1. Laguna adalah perairan dangkal di pesisir yang terpisah dari laut. 2. Pemisahan terjadi karena pembentukan gosong pasir (spit atau tombolo) oleh arus dan gelombang laut, seperti di Segara Anakan. 3. Jadi, jawaban yang benar adalah terpisahnya sebagian perairan laut oleh endapan pasir di pesisir." },
  { q: "Waduk Jatiluhur dan Waduk Gajah Mungkur termasuk danau buatan yang dibangun terutama untuk ...", options: ["PLTA, irigasi, dan pengendalian banjir", "tempat wisata saja", "budidaya air tawar saja", "penampung air hujan"], answer: 0, solution: "1. Waduk adalah danau buatan dari pembendungan sungai. 2. Waduk besar seperti Jatiluhur dan Gajah Mungkur berfungsi serbaguna: pembangkit listrik, irigasi pertanian, dan pengendali banjir. 3. Jadi, jawaban yang benar adalah PLTA, irigasi, dan pengendalian banjir." },
  { q: "Air tanah freatik memiliki ciri ...", options: ["terletak di antara dua lapisan kedap air", "berada di atas lapisan kedap air pertama dan dekat permukaan tanah", "memiliki tekanan ke atas yang besar", "hanya terdapat di daerah gurun"], answer: 1, solution: "1. Air tanah freatik (bebas) terletak di atas lapisan kedap pertama, relatif dekat permukaan. 2. Air tanah artesis (tertekan) terletak di antara dua lapisan kedap dan memiliki tekanan ke atas. 3. Jadi, jawaban yang benar adalah berada di atas lapisan kedap air pertama dan dekat permukaan tanah." },
  { q: "Lapisan batuan yang mampu menyimpan dan meloloskan air tanah dalam jumlah besar, misalnya lapisan pasir dan kerikil, disebut ...", options: ["akuitard", "akuifer", "akuiklud", "batuan kedap"], answer: 1, solution: "1. Akuifer adalah lapisan pembawa air yang permeabel sehingga dapat menyimpan dan mengalirkan air tanah. 2. Akuiklud dan batuan kedap tidak dapat meloloskan air, sedangkan akuitard hanya meloloskan sedikit. 3. Jadi, jawaban yang benar adalah akuifer." },
  { q: "Rawa lebak berbeda dengan rawa pasang surut. Pernyataan yang tepat tentang rawa lebak adalah ...", options: ["terletak di pesisir dan dipengaruhi pasang surut", "selalu kering sepanjang tahun", "terbentuk dari letusan gunung api", "terletak di pedalaman dan tergenang air terutama pada musim hujan"], answer: 3, solution: "1. Rawa pasang surut di pesisir dipengaruhi pasang surut air laut. 2. Rawa lebak terletak di pedalaman, tergenang pada musim hujan dan surut pada musim kemarau sehingga dapat dimanfaatkan untuk pertanian. 3. Jadi, jawaban yang benar adalah terletak di pedalaman dan tergenang air terutama pada musim hujan." },
  { q: "Intrusi air laut, yaitu merembesnya air laut ke dalam sumur-sumur air tanah di daerah pesisir, umumnya disebabkan oleh ...", options: ["pengambilan air tanah secara berlebihan", "curah hujan yang tinggi", "penanaman mangrove", "pembangunan waduk"], answer: 0, solution: "1. Pengambilan air tanah berlebihan menurunkan muka air tanah di daerah pesisir. 2. Tekanan air tanah yang turun membuat air laut yang lebih berat merembes masuk ke akuifer sehingga sumur menjadi asin. 3. Jadi, jawaban yang benar adalah pengambilan air tanah secara berlebihan." },
  { q: "Upaya konservasi air yang tepat untuk mencegah pencemaran sungai oleh limbah cair pabrik adalah ...", options: ["membuang limbah pada malam hari", "mewajibkan pengolahan limbah (IPAL) sebelum dibuang ke sungai", "memperlebar badan sungai", "mengeruk dasar sungai"], answer: 1, solution: "1. Limbah cair industri mengandung bahan berbahaya yang mencemari sungai. 2. Pengolahan melalui IPAL menurunkan kadar pencemar hingga memenuhi baku mutu sebelum dibuang ke perairan. 3. Jadi, jawaban yang benar adalah mewajibkan pengolahan limbah (IPAL) sebelum dibuang ke sungai." },
  { q: "Pasang purnama (spring tide) dengan kenaikan air laut maksimum terjadi pada saat ...", options: ["bulan separuh (kuartir)", "setiap tengah malam", "bulan purnama dan bulan baru ketika matahari, bumi, dan bulan segaris", "saat gerhana matahari saja"], answer: 2, solution: "1. Pasang purnama terjadi ketika gaya tarik bulan dan matahari saling memperkuat. 2. Hal ini terjadi saat matahari, bumi, dan bulan segaris, yaitu pada bulan purnama dan bulan baru. 3. Jadi, jawaban yang benar adalah bulan purnama dan bulan baru ketika ketiganya segaris." },
  { q: "Berdasarkan UNCLOS 1982, lebar Zona Ekonomi Eksklusif (ZEE) yang menjadi hak berdaulat Indonesia adalah ...", options: ["12 mil laut", "24 mil laut", "200 mil laut", "350 mil laut"], answer: 2, solution: "1. UNCLOS 1982 mengatur zona-zona laut suatu negara pantai. 2. Laut teritorial selebar 12 mil laut, sedangkan ZEE selebar 200 mil laut diukur dari garis pangkal, tempat negara berhak mengelola sumber daya alam. 3. Jadi, jawaban yang benar adalah 200 mil laut." },
  { q: "Gas yang paling banyak menyusun atmosfer bumi adalah ...", options: ["nitrogen sekitar 78%", "oksigen sekitar 78%", "karbon dioksida sekitar 21%", "hidrogen sekitar 50%"], answer: 0, solution: "1. Komposisi atmosfer bumi adalah nitrogen 78%, oksigen 21%, argon 0,93%, dan karbon dioksida 0,03%. 2. Gas dengan persentase terbesar adalah nitrogen. 3. Jadi, jawaban yang benar adalah nitrogen sekitar 78%." },
  { q: "Lapisan ozon yang melindungi bumi dari radiasi ultraviolet terdapat di lapisan ...", options: ["troposfer", "mesosfer", "stratosfer", "eksosfer"], answer: 2, solution: "1. Lapisan ozon terkonsentrasi pada ketinggian sekitar 15-35 km. 2. Ketinggian tersebut berada di lapisan stratosfer, di atas troposfer tempat terjadinya cuaca. 3. Jadi, jawaban yang benar adalah stratosfer." },
  { q: "Meteor yang memasuki atmosfer bumi umumnya terbakar habis di lapisan ...", options: ["troposfer", "stratosfer", "mesosfer", "termosfer"], answer: 2, solution: "1. Meteor bergesekan dengan partikel udara sehingga terbakar. 2. Pembakaran ini umumnya terjadi di lapisan mesosfer yang berada di atas stratosfer. 3. Jadi, jawaban yang benar adalah mesosfer." },
  { q: "Lapisan atmosfer yang dapat memantulkan gelombang radio dan tempat terjadinya aurora adalah lapisan ...", options: ["stratosfer", "mesosfer", "eksosfer", "termosfer (ionosfer)"], answer: 3, solution: "1. Di termosfer, partikel gas mengalami ionisasi membentuk lapisan ionosfer. 2. Lapisan bermuatan ini memantulkan gelombang radio dan menjadi tempat terjadinya aurora akibat partikel matahari. 3. Jadi, jawaban yang benar adalah termosfer (ionosfer)." },
  { q: "Kelembapan relatif udara yang dinyatakan dalam persen menunjukkan ...", options: ["perbandingan jumlah uap air aktual dengan jumlah maksimum uap air yang dapat ditampung udara pada suhu tersebut", "jumlah uap air per meter kubik udara", "suhu titik embun udara", "tekanan uap air jenuh"], answer: 0, solution: "1. Kelembapan relatif membandingkan kandungan uap air aktual dengan kapasitas maksimumnya. 2. Dinyatakan dalam persen; 100% berarti udara jenuh dan siap mengembun. 3. Jadi, jawaban yang benar adalah perbandingan jumlah uap air aktual dengan jumlah maksimumnya pada suhu tersebut." },
  { q: "Awan cirrus memiliki ciri ...", options: ["gumpalan tebal berwarna gelap penyebab hujan", "serabut halus berwarna putih seperti bulu, terdiri dari kristal es, dan menandakan cuaca cerah", "lapisan merata berwarna kelabu di ketinggian rendah", "menjulang tinggi seperti bunga kol penyebab hujan deras"], answer: 1, solution: "1. Cirrus adalah awan tinggi yang terbentuk dari kristal es. 2. Bentuknya berupa serabut halus berwarna putih dan biasanya menandakan cuaca cerah. 3. Jadi, jawaban yang benar adalah serabut halus berwarna putih seperti bulu, terdiri dari kristal es." },
  { q: "Awan yang berwarna gelap, berlapis tebal, dan menutupi langit sehingga menimbulkan hujan yang merata adalah awan ...", options: ["cumulus", "altocumulus", "nimbostratus", "cirrus"], answer: 2, solution: "1. Awan rendah pembawa hujan adalah nimbostratus. 2. Cirinya berlapis tebal, berwarna kelabu gelap, dan menutupi langit sehingga menimbulkan hujan yang merata dan cukup lama. 3. Jadi, jawaban yang benar adalah nimbostratus." },
  { q: "Awan cumulonimbus memiliki ciri ...", options: ["tipis dan tinggi", "berlapis kelabu di ketinggian sedang", "gumpalan kecil berderet", "menjulang tinggi seperti menara dan menimbulkan hujan deras disertai petir"], answer: 3, solution: "1. Cumulonimbus adalah awan vertikal yang tumbuh menjulang tinggi. 2. Bentuknya seperti menara atau bunga kol raksasa dan menghasilkan hujan deras, petir, bahkan angin kencang. 3. Jadi, jawaban yang benar adalah menjulang tinggi seperti menara dan menimbulkan hujan deras disertai petir." },
  { q: "Menurut klasifikasi iklim Koppen, wilayah beriklim tipe E memiliki ciri ...", options: ["bersalju atau beres sepanjang tahun seperti di daerah kutub", "kering dengan curah hujan sangat rendah", "hujan sepanjang tahun dan panas", "sedang dengan empat musim yang jelas"], answer: 0, solution: "1. Klasifikasi Koppen membagi iklim menjadi A (tropis), B (kering), C (sedang), D (dingin), dan E (kutub). 2. Tipe E adalah iklim kutub atau es dengan suhu sangat rendah sepanjang tahun. 3. Jadi, jawaban yang benar adalah bersalju atau beres sepanjang tahun seperti di daerah kutub." },
  { q: "Suatu daerah memiliki nilai Q Schmidt-Ferguson sebesar 50%. Tipe iklim daerah tersebut adalah ...", options: ["tipe A", "tipe B", "tipe C", "tipe D"], answer: 2, solution: "1. Nilai Q Schmidt-Ferguson = (jumlah bulan kering / jumlah bulan basah) x 100%. 2. Klasifikasi Schmidt-Ferguson: tipe A (Q < 14,3), tipe B (Q 14,3-33,3), tipe C (Q 33,3-60), tipe D (Q 60-100). 3. Nilai Q = 50 masuk dalam rentang 33,3-60, jadi tipe iklimnya adalah tipe C." },
  { q: "Klasifikasi iklim yang disusun berdasarkan jumlah bulan basah berurutan dan digunakan untuk menentukan pola tanam pertanian adalah klasifikasi ...", options: ["Koppen", "Oldeman", "Schmidt-Ferguson", "Junghuhn"], answer: 1, solution: "1. Klasifikasi Oldeman dirancang khusus untuk kepentingan pertanian di Indonesia. 2. Dasarnya adalah jumlah bulan basah berurutan untuk menentukan kesesuaian pola tanam, terutama padi. 3. Jadi, jawaban yang benar adalah Oldeman." },
  { q: "Angin laut bertiup pada siang hari dari ...", options: ["darat ke laut", "gunung ke lembah", "lembah ke gunung", "laut ke darat"], answer: 3, solution: "1. Pada siang hari daratan lebih cepat panas daripada lautan sehingga tekanan udara di darat lebih rendah. 2. Angin bertiup dari tekanan tinggi (laut) ke tekanan rendah (darat). 3. Jadi, jawaban yang benar adalah laut ke darat." },
  { q: "Pada malam hari, udara dingin dari puncak gunung turun ke lembah. Angin tersebut disebut angin ...", options: ["lembah", "laut", "gunung", "muson"], answer: 2, solution: "1. Pada malam hari puncak gunung lebih cepat dingin sehingga tekanan udara di sana lebih tinggi. 2. Udara bergerak dari gunung turun ke lembah dan disebut angin gunung. 3. Jadi, jawaban yang benar adalah gunung." },
  { q: "Angin fohn Bohorok yang bersifat panas dan kering bertiup di daerah ...", options: ["Deli, Sumatra Utara", "Cirebon, Jawa Barat", "Pasuruan, Jawa Timur", "Makassar, Sulawesi Selatan"], answer: 0, solution: "1. Angin fohn adalah angin yang turun dari pegunungan dan bersifat panas serta kering. 2. Angin Bohorok bertiup di daerah Deli, Sumatra Utara; sedangkan Kumbang di Cirebon, Gending di Pasuruan, dan Brubu di Makassar. 3. Jadi, jawaban yang benar adalah Deli, Sumatra Utara." },
  { q: "Angin Gending yang bertiup di daerah Pasuruan, Jawa Timur termasuk jenis angin ...", options: ["muson", "fohn", "lembah", "darat"], answer: 1, solution: "1. Angin Gending bertiup di Pasuruan dan bersifat panas serta kering. 2. Sifat panas dan kering setelah melewati pegunungan adalah ciri angin fohn. 3. Jadi, jawaban yang benar adalah fohn." },
  { q: "Hujan zenithal (konveksi) terjadi karena ...", options: ["udara dipaksa naik melewati pegunungan", "pertemuan massa udara panas dan dingin", "pemanasan udara yang kuat sehingga udara naik secara vertikal lalu mengembun", "penyemaian awan dengan bahan kimia"], answer: 2, solution: "1. Hujan zenithal terjadi di daerah khatulistiwa yang mendapat penyinaran matahari terik. 2. Udara panas memuai dan naik secara vertikal (konveksi), lalu mendingin dan mengembun menjadi hujan pada siang atau sore hari. 3. Jadi, jawaban yang benar adalah pemanasan udara yang kuat sehingga udara naik secara vertikal lalu mengembun." },
  { q: "Hujan frontal (siklon) terjadi akibat ...", options: ["pemanasan matahari yang terik", "udara naik karena pegunungan", "hembusan angin muson", "pertemuan massa udara panas dan massa udara dingin"], answer: 3, solution: "1. Hujan frontal terjadi di daerah pertemuan dua massa udara yang berbeda suhunya. 2. Massa udara panas yang ringan terangkat oleh massa udara dingin yang berat, lalu mengembun menjadi hujan di sepanjang garis front. 3. Jadi, jawaban yang benar adalah pertemuan massa udara panas dan massa udara dingin." },
  { q: "Hujan buatan dibuat dengan cara ...", options: ["menyemai awan dengan zat higroskopis seperti NaCl agar uap air mengembun", "mendinginkan udara dengan es", "memompa air ke awan", "menembakkan roket ke langit"], answer: 0, solution: "1. Hujan buatan memanfaatkan awan yang sudah mengandung uap air tetapi belum turun sebagai hujan. 2. Awan disemai dengan zat higroskopis seperti NaCl atau AgI yang menjadi inti kondensasi sehingga uap air mengembun dan jatuh sebagai hujan. 3. Jadi, jawaban yang benar adalah menyemai awan dengan zat higroskopis seperti NaCl agar uap air mengembun." },
  { q: "Dampak anomali iklim El Nino bagi Indonesia adalah ...", options: ["curah hujan sangat tinggi dan banjir", "musim kemarau yang lebih panjang dan kekeringan", "suhu udara sangat dingin", "angin puting beliung meningkat"], answer: 1, solution: "1. El Nino ditandai memanasnya suhu muka laut di Samudra Pasifik bagian timur. 2. Kondisi ini melemahkan pembentukan awan hujan di Indonesia sehingga musim kemarau menjadi lebih panjang dan terjadi kekeringan. 3. Jadi, jawaban yang benar adalah musim kemarau yang lebih panjang dan kekeringan." },
  { q: "Dampak anomali iklim La Nina bagi Indonesia adalah ...", options: ["kemarau panjang", "gagal panen karena kekeringan", "curah hujan di atas normal sehingga rawan banjir", "menurunnya permukaan air laut"], answer: 2, solution: "1. La Nina adalah kebalikan El Nino, yaitu mendinginnya suhu muka laut di Pasifik timur. 2. Kondisi ini memperkuat pembentukan awan di Indonesia sehingga curah hujan di atas normal dan rawan banjir serta longsor. 3. Jadi, jawaban yang benar adalah curah hujan di atas normal sehingga rawan banjir." },
  { q: "Indian Ocean Dipole (IOD) positif ditandai dengan ...", options: ["suhu muka laut di perairan Indonesia lebih hangat", "curah hujan tinggi di Indonesia", "melemahnya angin muson barat", "suhu muka laut Samudra Hindia bagian barat lebih hangat sedangkan bagian timur (dekat Indonesia) lebih dingin"], answer: 3, solution: "1. IOD adalah perbedaan suhu muka laut antara Samudra Hindia barat dan timur. 2. Pada fase positif, bagian barat (dekat Afrika) lebih hangat dan bagian timur (dekat Indonesia) lebih dingin sehingga pasokan uap air ke Indonesia berkurang dan kemarau menguat. 3. Jadi, jawaban yang benar adalah suhu muka laut bagian barat lebih hangat sedangkan bagian timur lebih dingin." },
  { q: "Mekanisme efek rumah kaca yang menyebabkan pemanasan global adalah ...", options: ["gas rumah kaca menyerap dan menahan radiasi infra merah dari permukaan bumi sehingga suhu udara naik", "menipisnya lapisan ozon", "meningkatnya radiasi ultraviolet", "berkurangnya uap air di atmosfer"], answer: 0, solution: "1. Permukaan bumi yang dipanaskan matahari memancarkan radiasi infra merah ke atmosfer. 2. Gas rumah kaca seperti CO2 dan metana menyerap radiasi tersebut dan menahannya di atmosfer sehingga suhu bumi naik. 3. Jadi, jawaban yang benar adalah gas rumah kaca menyerap dan menahan radiasi infra merah sehingga suhu udara naik." },
  { q: "Berikut ini yang termasuk upaya mitigasi (pengurangan) pemanasan global adalah ...", options: ["membangun tanggul laut", "mengurangi emisi gas rumah kaca dan beralih ke energi terbarukan", "membuat sumur resapan", "relokasi penduduk pesisir"], answer: 1, solution: "1. Mitigasi bertujuan mengurangi penyebab pemanasan global, sedangkan adaptasi bertujuan menyesuaikan diri dengan dampaknya. 2. Mengurangi emisi dan beralih ke energi terbarukan menekan sumber pemanasan global, sedangkan tanggul, sumur resapan, dan relokasi termasuk adaptasi. 3. Jadi, jawaban yang benar adalah mengurangi emisi gas rumah kaca dan beralih ke energi terbarukan." },
  { q: "Gas CFC yang dulu banyak digunakan pada kulkas dan AC berbahaya bagi atmosfer karena ...", options: ["menyebabkan hujan asam", "menambah gas oksigen", "menurunkan suhu bumi", "merusak lapisan ozon"], answer: 3, solution: "1. Gas CFC yang lepas ke atmosfer naik hingga mencapai lapisan stratosfer. 2. Di sana CFC terurai dan melepaskan klor yang merusak molekul ozon sehingga lapisan ozon menipis. 3. Jadi, jawaban yang benar adalah merusak lapisan ozon." },
  { q: "Curah hujan yang tinggi sepanjang tahun di Kalimantan menyebabkan tumbuhnya hutan hujan tropis yang lebat. Hal ini menunjukkan faktor ... sangat berpengaruh terhadap persebaran flora.", options: ["iklim", "relief", "biotik", "manusia"], answer: 0, solution: "1. Faktor iklim meliputi curah hujan, suhu, dan kelembapan udara. 2. Curah hujan tinggi sepanjang tahun mendukung pertumbuhan hutan hujan tropis yang lebat di Kalimantan. 3. Jadi, jawaban yang benar adalah iklim." },
  { q: "Bioma sabana memiliki ciri ...", options: ["padang rumput luas tanpa pohon sama sekali", "padang rumput dengan pohon-pohon yang tumbuh jarang dan tersebar", "hutan lebat yang hijau sepanjang tahun", "tumbuhan kaktus yang berduri"], answer: 1, solution: "1. Sabana adalah bioma padang rumput tropis dengan musim kemarau yang jelas. 2. Cirinya adalah hamparan rumput dengan pohon-pohon seperti akasia yang tumbuh jarang dan tersebar. 3. Jadi, jawaban yang benar adalah padang rumput dengan pohon-pohon yang tumbuh jarang dan tersebar." },
  { q: "Perbedaan utama bioma stepa dan sabana adalah ...", options: ["stepa lebih basah daripada sabana", "stepa beriklim dingin", "keduanya tidak ada bedanya", "stepa berupa padang rumput tanpa pohon sedangkan sabana memiliki pohon yang tumbuh jarang"], answer: 3, solution: "1. Sabana beriklim tropis dengan pohon yang tumbuh jarang di antara hamparan rumput. 2. Stepa beriklim sedang yang lebih kering sehingga hanya ditumbuhi rumput pendek tanpa pohon. 3. Jadi, jawaban yang benar adalah stepa berupa padang rumput tanpa pohon sedangkan sabana memiliki pohon yang tumbuh jarang." },
  { q: "Tumbuhan kaktus yang berdaun kecil seperti duri dan berakar panjang merupakan adaptasi terhadap bioma ...", options: ["tundra", "taiga", "sabana", "gurun"], answer: 3, solution: "1. Bioma gurun bercurah hujan sangat rendah dan penguapan sangat tinggi. 2. Kaktus beradaptasi dengan daun berupa duri untuk mengurangi penguapan dan akar panjang untuk mencari air. 3. Jadi, jawaban yang benar adalah gurun." },
  { q: "Bioma taiga yang didominasi pohon berdaun jarum (konifer) seperti pinus terdapat di daerah ...", options: ["beriklim dingin di belahan bumi utara seperti Siberia dan Kanada", "khatulistiwa yang panas", "kutub yang membeku", "gurun yang kering"], answer: 0, solution: "1. Taiga adalah hutan konifer berdaun jarum yang tahan dingin. 2. Bioma ini membentang luas di daerah beriklim dingin belahan bumi utara seperti Siberia dan Kanada, di antara tundra dan hutan gugur. 3. Jadi, jawaban yang benar adalah beriklim dingin di belahan bumi utara seperti Siberia dan Kanada." },
  { q: "Bioma tundra memiliki ciri ...", options: ["hutan lebat berdaun lebar", "padang lumut dengan tanah yang membeku (permafrost) dan hampir tidak ada pohon", "padang rumput dengan pohon jarang", "hutan konifer yang lebat"], answer: 1, solution: "1. Tundra terdapat di sekitar lingkaran kutub dengan suhu sangat rendah. 2. Tanah bagian bawahnya membeku permanen (permafrost) sehingga hanya lumut dan tumbuhan pendek yang dapat tumbuh, hampir tanpa pohon. 3. Jadi, jawaban yang benar adalah padang lumut dengan tanah yang membeku dan hampir tidak ada pohon." },
  { q: "Tapir, armadillo, dan kukang merupakan contoh fauna kawasan ...", options: ["Neartik", "Ethiopia", "Neotropik", "Paleartik"], answer: 2, solution: "1. Persebaran fauna dunia dibagi menjadi beberapa kawasan biogeografi. 2. Kawasan Neotropik meliputi Amerika Tengah dan Selatan dengan fauna khas seperti tapir, armadillo, kukang, dan llama. 3. Jadi, jawaban yang benar adalah Neotropik." },
  { q: "Jerapah, zebra, dan singa merupakan contoh fauna kawasan ...", options: ["Oriental", "Australia", "Neotropik", "Ethiopia"], answer: 3, solution: "1. Kawasan Ethiopia meliputi benua Afrika di selatan Gurun Sahara. 2. Fauna khasnya adalah mamalia besar seperti jerapah, zebra, singa, dan gajah afrika. 3. Jadi, jawaban yang benar adalah Ethiopia." },
  { q: "Harimau, gajah asia, dan orangutan merupakan contoh fauna kawasan ...", options: ["Oriental", "Neartik", "Ethiopia", "Australia"], answer: 0, solution: "1. Kawasan Oriental meliputi Asia Selatan dan Asia Tenggara termasuk Indonesia bagian barat. 2. Fauna khasnya antara lain harimau, gajah asia, orangutan, dan badak. 3. Jadi, jawaban yang benar adalah Oriental." },
  { q: "Hutan musim di Indonesia, misalnya hutan jati di Jawa, memiliki ciri ...", options: ["hijau sepanjang tahun", "menggugurkan daunnya pada musim kemarau", "tumbuh di daerah berawa", "didominasi tumbuhan lumut"], answer: 1, solution: "1. Hutan musim tumbuh di daerah dengan musim kemarau yang jelas seperti di Jawa. 2. Untuk mengurangi penguapan saat kemarau, pohon-pohonnya menggugurkan daun, misalnya jati. 3. Jadi, jawaban yang benar adalah menggugurkan daunnya pada musim kemarau." },
  { q: "Manfaat ekologis hutan bakau (mangrove) di pesisir adalah ...", options: ["sumber kayu bakar utama", "menambah salinitas air laut", "menahan abrasi dan menjadi tempat berkembang biaknya ikan", "lahan pertanian yang subur"], answer: 2, solution: "1. Hutan mangrove tumbuh di pesisir dengan akar tunjang dan akar napas yang kuat. 2. Akar-akarnya menahan hempasan gelombang sehingga mencegah abrasi dan menjadi habitat serta tempat berkembang biak ikan, udang, dan kepiting. 3. Jadi, jawaban yang benar adalah menahan abrasi dan menjadi tempat berkembang biaknya ikan." },
  { q: "Burung maleo yang bertelur di pasir panas merupakan fauna endemik ...", options: ["Papua", "Kalimantan", "Jawa", "Sulawesi"], answer: 3, solution: "1. Fauna endemik adalah hewan yang hanya terdapat di daerah tertentu. 2. Burung maleo hanya ditemukan di Sulawesi dan bertelur dengan memanfaatkan panas pasir atau panas bumi. 3. Jadi, jawaban yang benar adalah Sulawesi." },
  { q: "Orangutan merupakan fauna endemik Indonesia yang habitat alaminya terdapat di ...", options: ["Kalimantan dan Sumatra", "Jawa dan Bali", "Sulawesi dan Maluku", "Papua dan Nusa Tenggara"], answer: 0, solution: "1. Orangutan adalah kera besar yang hanya hidup di hutan hujan tropis. 2. Di dunia, orangutan liar hanya terdapat di Pulau Kalimantan dan Pulau Sumatra. 3. Jadi, jawaban yang benar adalah Kalimantan dan Sumatra." },
  { q: "Perbedaan cagar alam dan suaka margasatwa adalah ...", options: ["tidak ada perbedaan", "cagar alam melindungi ekosistem beserta flora dan faunanya secara keseluruhan, sedangkan suaka margasatwa khusus melindungi habitat satwa", "cagar alam boleh dikunjungi wisatawan sedangkan suaka margasatwa tidak", "suaka margasatwa lebih luas daripada cagar alam"], answer: 1, solution: "1. Cagar alam bertujuan melindungi keanekaragaman tumbuhan, satwa, dan ekosistemnya secara keseluruhan dengan perlindungan ketat. 2. Suaka margasatwa lebih khusus ditujukan untuk melindungi habitat dan kelangsungan hidup jenis satwa tertentu, misalnya suaka margasatwa Way Kambas untuk gajah. 3. Jadi, jawaban yang benar adalah cagar alam melindungi ekosistem beserta flora dan faunanya secara keseluruhan, sedangkan suaka margasatwa khusus melindungi habitat satwa." },
  { q: "Dampak deforestasi (penggundulan hutan) bagi daerah aliran sungai adalah ...", options: ["menambah debit mata air", "menurunkan suhu udara", "menambah kesuburan tanah", "meningkatkan aliran permukaan sehingga rawan banjir dan longsor"], answer: 3, solution: "1. Hutan berfungsi menyerap air hujan melalui intersepsi dan infiltrasi. 2. Jika hutan digunduli, air hujan langsung menjadi limpasan permukaan yang besar sehingga sungai cepat meluap dan lereng rawan longsor. 3. Jadi, jawaban yang benar adalah meningkatkan aliran permukaan sehingga rawan banjir dan longsor." },
  { q: "Suatu daerah memiliki penduduk laki-laki 105.000 jiwa dan perempuan 100.000 jiwa. Sex ratio daerah tersebut adalah ...", options: ["105", "95", "205", "0,95"], answer: 0, solution: "1. Sex ratio = (jumlah penduduk laki-laki / jumlah penduduk perempuan) x 100. 2. Sex ratio = (105.000 / 100.000) x 100 = 105. 3. Artinya terdapat 105 penduduk laki-laki untuk setiap 100 penduduk perempuan, jadi jawaban yang benar adalah 105." },
  { q: "Yang dimaksud angkatan kerja adalah ...", options: ["seluruh penduduk suatu negara", "penduduk usia 15 tahun ke atas yang bekerja atau sedang mencari pekerjaan", "penduduk yang sudah pensiun", "anak-anak usia sekolah"], answer: 1, solution: "1. Angkatan kerja adalah bagian penduduk usia produktif yang aktif secara ekonomi. 2. Batas usia kerja yang digunakan adalah 15 tahun ke atas, mencakup yang sudah bekerja maupun yang sedang mencari pekerjaan (pengangguran). 3. Jadi, jawaban yang benar adalah penduduk usia 15 tahun ke atas yang bekerja atau sedang mencari pekerjaan." },
  { q: "Piramida penduduk stasioner menunjukkan ...", options: ["angka kelahiran sangat tinggi", "angka kematian sangat tinggi", "jumlah kelahiran dan kematian relatif seimbang sehingga pertumbuhan penduduk rendah", "penduduk didominasi usia tua"], answer: 2, solution: "1. Piramida stasioner berbentuk seperti granat atau sarang tawon dengan lebar tiap kelompok umur hampir sama. 2. Bentuk ini terjadi karena angka kelahiran dan kematian relatif seimbang sehingga pertumbuhan penduduk rendah atau nol. 3. Jadi, jawaban yang benar adalah jumlah kelahiran dan kematian relatif seimbang sehingga pertumbuhan penduduk rendah." },
  { q: "Piramida penduduk tua (konstruktif) memiliki ciri ...", options: ["alas lebar dan puncak meruncing", "jumlah penduduk usia muda sangat besar", "pertumbuhan penduduk sangat cepat", "alas sempit karena angka kelahiran rendah dan harapan hidup tinggi"], answer: 3, solution: "1. Piramida tua berbentuk seperti batu nisan dengan alas yang sempit. 2. Alas sempit menunjukkan angka kelahiran rendah, sedangkan bagian atas yang lebar menunjukkan harapan hidup tinggi sehingga banyak penduduk usia tua. 3. Jadi, jawaban yang benar adalah alas sempit karena angka kelahiran rendah dan harapan hidup tinggi." },
  { q: "Berikut ini yang termasuk faktor pendorong (push factor) migrasi adalah ...", options: ["sempitnya lahan pertanian dan sulitnya mencari pekerjaan di daerah asal", "tingginya upah di kota tujuan", "lengkapnya fasilitas pendidikan di kota", "tersedianya lapangan pekerjaan di daerah tujuan"], answer: 0, solution: "1. Push factor adalah kondisi buruk di daerah asal yang mendorong penduduk pergi. 2. Sempitnya lahan dan sulitnya pekerjaan adalah masalah di daerah asal, sedangkan upah tinggi, fasilitas lengkap, dan lapangan pekerjaan adalah daya tarik daerah tujuan (pull factor). 3. Jadi, jawaban yang benar adalah sempitnya lahan pertanian dan sulitnya mencari pekerjaan di daerah asal." },
  { q: "Berikut ini yang termasuk faktor penarik (pull factor) migrasi adalah ...", options: ["bencana alam di daerah asal", "tersedianya lapangan pekerjaan dan upah yang lebih tinggi di daerah tujuan", "konflik sosial di daerah asal", "kepadatan penduduk di daerah asal"], answer: 1, solution: "1. Pull factor adalah daya tarik di daerah tujuan yang menarik pendatang. 2. Lapangan pekerjaan dan upah yang lebih tinggi di daerah tujuan menarik penduduk untuk bermigrasi, sedangkan bencana, konflik, dan kepadatan adalah pendorong dari daerah asal. 3. Jadi, jawaban yang benar adalah tersedianya lapangan pekerjaan dan upah yang lebih tinggi di daerah tujuan." },
  { q: "Seorang warga negara Indonesia pindah dan menetap di Malaysia untuk bekerja. Ditinjau dari Indonesia, perpindahan tersebut disebut ...", options: ["imigrasi", "remigrasi", "emigrasi", "transmigrasi"], answer: 2, solution: "1. Emigrasi adalah perpindahan penduduk keluar dari suatu negara, sedangkan imigrasi adalah perpindahan masuk ke suatu negara. 2. Warga Indonesia yang pindah ke Malaysia berarti keluar dari Indonesia, sehingga dari sudut pandang Indonesia disebut emigrasi. 3. Jadi, jawaban yang benar adalah emigrasi." },
  { q: "Program perpindahan penduduk dari pulau yang padat ke pulau yang jarang penduduknya dalam satu negara disebut ...", options: ["urbanisasi", "ruralisasi", "imigrasi", "transmigrasi"], answer: 3, solution: "1. Transmigrasi adalah perpindahan penduduk antarwilayah dalam satu negara, umumnya dari daerah padat ke daerah jarang penduduk. 2. Di Indonesia, program ini memindahkan penduduk dari Jawa ke Sumatra, Kalimantan, dan Papua untuk pemerataan persebaran penduduk. 3. Jadi, jawaban yang benar adalah transmigrasi." },
  { q: "Penduduk yang setiap hari pergi bekerja ke kota dan pulang kembali ke rumahnya di desa pada sore hari melakukan mobilitas ...", options: ["komutasi", "transmigrasi", "urbanisasi", "remigrasi"], answer: 0, solution: "1. Komutasi (commuting) adalah mobilitas ulang-alik harian antara tempat tinggal dan tempat bekerja. 2. Pelakunya pergi pada pagi hari dan kembali pada sore atau malam hari di hari yang sama tanpa pindah tempat tinggal. 3. Jadi, jawaban yang benar adalah komutasi." },
  { q: "Dampak negatif urbanisasi yang tidak terkendali bagi kota adalah ...", options: ["meningkatnya pendapatan daerah", "munculnya permukiman kumuh dan pengangguran", "berkurangnya kemacetan", "meningkatnya kualitas pendidikan"], answer: 1, solution: "1. Urbanisasi yang tidak terkendali membuat pertumbuhan penduduk kota melampaui daya tampung lapangan kerja dan perumahan. 2. Akibatnya muncul permukiman kumuh (slum area), pengangguran, kemacetan, dan kriminalitas. 3. Jadi, jawaban yang benar adalah munculnya permukiman kumuh dan pengangguran." },
  { q: "Tujuan utama program Keluarga Berencana (KB) adalah ...", options: ["menambah jumlah penduduk", "memeratakan persebaran penduduk", "menekan laju pertumbuhan penduduk melalui keluarga kecil", "meningkatkan angka kelahiran"], answer: 2, solution: "1. Program KB digalakkan untuk mengatasi ledakan penduduk. 2. Tujuannya menekan laju pertumbuhan penduduk dengan mewujudkan keluarga kecil yang sejahtera melalui pengaturan kelahiran. 3. Jadi, jawaban yang benar adalah menekan laju pertumbuhan penduduk melalui keluarga kecil." },
  { q: "Pencatatan peristiwa kependudukan seperti kelahiran, kematian, dan perpindahan penduduk yang dilakukan secara terus-menerus disebut ...", options: ["sensus", "survei", "proyeksi", "registrasi"], answer: 3, solution: "1. Sensus adalah pencacahan seluruh penduduk pada waktu tertentu, survei hanya mengambil sampel. 2. Registrasi penduduk adalah pencatatan peristiwa kependudukan (lahir, mati, pindah, kawin) secara terus-menerus oleh instansi berwenang. 3. Jadi, jawaban yang benar adalah registrasi." },
  { q: "Indeks Pembangunan Manusia (IPM) disusun berdasarkan tiga komponen, yaitu ...", options: ["angka harapan hidup, pendidikan, dan pendapatan", "kepadatan penduduk, kelahiran, dan kematian", "pertanian, industri, dan jasa", "ekspor, impor, dan investasi"], answer: 0, solution: "1. IPM mengukur kualitas hidup manusia, bukan sekadar jumlah penduduk atau ekonomi. 2. Tiga dimensinya adalah kesehatan (angka harapan hidup), pendidikan (rata-rata dan harapan lama sekolah), dan standar hidup layak (pendapatan per kapita). 3. Jadi, jawaban yang benar adalah angka harapan hidup, pendidikan, dan pendapatan." },
  { q: "Petani yang tidak memiliki pekerjaan pada musim paceklik (menunggu musim tanam) termasuk pengangguran ...", options: ["terbuka", "musiman", "friksional", "struktural"], answer: 1, solution: "1. Pengangguran musiman terjadi karena pekerjaan hanya tersedia pada musim tertentu. 2. Petani menganggur saat paceklik dan bekerja kembali saat musim tanam tiba, sesuai siklus musim pertanian. 3. Jadi, jawaban yang benar adalah musiman." },
  { q: "Wilayah formal ditentukan berdasarkan ...", options: ["fungsi dan keterkaitan antarwilayah", "persepsi masyarakat", "keseragaman ciri tertentu seperti iklim dan jenis tanah", "jarak ke pusat kota"], answer: 2, solution: "1. Wilayah formal (uniform region) dicirikan oleh keseragaman atau homogenitas. 2. Contohnya wilayah iklim tropis, wilayah pertanian lahan basah, atau wilayah bahasa tertentu yang memiliki ciri sama di seluruh bagiannya. 3. Jadi, jawaban yang benar adalah keseragaman ciri tertentu seperti iklim dan jenis tanah." },
  { q: "Kawasan Jabodetabek merupakan contoh wilayah fungsional karena ...", options: ["memiliki iklim yang sama", "dibatasi garis administratif yang tegas", "dipersepsikan sebagai satu kesatuan budaya", "memiliki pusat kegiatan (Jakarta) yang saling terkait dengan wilayah di sekitarnya"], answer: 3, solution: "1. Wilayah fungsional (nodal region) ditentukan oleh fungsi dan keterkaitan antarwilayah. 2. Jabodetabek memiliki Jakarta sebagai pusat kegiatan yang terhubung dengan Bogor, Depok, Tangerang, dan Bekasi melalui arus komuter, barang, dan jasa. 3. Jadi, jawaban yang benar adalah memiliki pusat kegiatan yang saling terkait dengan wilayah di sekitarnya." },
  { q: "Wilayah vernakular terbentuk berdasarkan ...", options: ["persepsi, identitas, atau perasaan memiliki masyarakat terhadap suatu wilayah", "keseragaman fisik yang dapat diukur", "fungsi ekonomi yang terpusat", "batas administratif resmi"], answer: 0, solution: "1. Wilayah vernakular (perseptual) tidak memiliki batas tegas yang dapat diukur. 2. Wilayah ini terbentuk dari persepsi dan identitas masyarakat, misalnya Tanah Batak atau kawasan Priangan. 3. Jadi, jawaban yang benar adalah persepsi, identitas, atau perasaan memiliki masyarakat terhadap suatu wilayah." },
  { q: "Menurut Gunnar Myrdal, backwash effect adalah ...", options: ["menyebarnya pembangunan dari pusat ke daerah sekitarnya", "tersedotnya sumber daya dan tenaga kerja dari daerah pinggiran ke pusat pertumbuhan", "menetesnya hasil pembangunan ke lapisan bawah", "terbentuknya kutub pertumbuhan baru"], answer: 1, solution: "1. Myrdal mengemukakan dua efek pembangunan wilayah yang bertolak belakang. 2. Backwash effect adalah efek negatif berupa tersedotnya modal, sumber daya, dan tenaga kerja terampil dari daerah pinggiran ke pusat pertumbuhan sehingga kesenjangan melebar. 3. Jadi, jawaban yang benar adalah tersedotnya sumber daya dan tenaga kerja dari daerah pinggiran ke pusat pertumbuhan." },
  { q: "Menurut Hirschman, polarization effect dalam pembangunan wilayah berarti ...", options: ["pemerataan pembangunan", "penyebaran teknologi ke desa", "pemusatan kegiatan ekonomi di pusat pertumbuhan yang merugikan daerah sekitarnya", "tetesan hasil pembangunan ke masyarakat bawah"], answer: 2, solution: "1. Hirschman mengemukakan trickle down effect (tetesan ke bawah) dan polarization effect. 2. Polarization effect adalah pemusatan kegiatan ekonomi di pusat pertumbuhan yang justru menghambat dan merugikan perkembangan daerah sekitarnya. 3. Jadi, jawaban yang benar adalah pemusatan kegiatan ekonomi di pusat pertumbuhan yang merugikan daerah sekitarnya." },
  { q: "Teori pusat-pinggiran (core-periphery) dari John Friedman menyatakan bahwa ...", options: ["semua wilayah berkembang merata", "desa lebih maju daripada kota", "pusat pertumbuhan tidak berpengaruh", "wilayah pusat (core) mendominasi dan memengaruhi perkembangan wilayah pinggiran (periphery)"], answer: 3, solution: "1. Friedman membagi wilayah menjadi pusat (core) dan pinggiran (periphery). 2. Wilayah pusat yang maju mendominasi, mengendalikan, dan memengaruhi perkembangan wilayah pinggiran di sekitarnya. 3. Jadi, jawaban yang benar adalah wilayah pusat mendominasi dan memengaruhi perkembangan wilayah pinggiran." },
  { q: "Menurut teori gravitasi dalam interaksi wilayah, kekuatan interaksi antara dua wilayah ...", options: ["berbanding lurus dengan jumlah penduduk kedua wilayah dan berbanding terbalik dengan kuadrat jaraknya", "berbanding terbalik dengan jumlah penduduk", "hanya ditentukan oleh jarak", "sama untuk semua pasangan wilayah"], answer: 0, solution: "1. Teori gravitasi mengadaptasi hukum gravitasi Newton ke interaksi wilayah. 2. Rumusnya I = (P1 x P2) / d kuadrat, artinya interaksi makin kuat jika penduduk besar dan jarak dekat. 3. Jadi, jawaban yang benar adalah berbanding lurus dengan jumlah penduduk kedua wilayah dan berbanding terbalik dengan kuadrat jaraknya." },
  { q: "Desa swasembada memiliki ciri ...", options: ["masih sangat tradisional dan tertutup", "sudah maju dengan teknologi modern dan mampu mengembangkan potensinya sendiri", "sedang dalam masa peralihan", "tergantung sepenuhnya pada bantuan kota"], answer: 1, solution: "1. Klasifikasi perkembangan desa terdiri dari swadaya (tradisional), swakarya (transisi), dan swasembada (maju). 2. Desa swasembada sudah maju, memanfaatkan teknologi modern, dan mampu mengembangkan potensi desanya secara mandiri. 3. Jadi, jawaban yang benar adalah sudah maju dengan teknologi modern dan mampu mengembangkan potensinya sendiri." },
  { q: "Menurut teori konsentris Burgess, struktur ruang kota berkembang ...", options: ["membentuk sektor sepanjang jalur transportasi", "memiliki banyak inti kegiatan", "melingkar dengan pusat kegiatan (CBD) di tengah", "memanjang mengikuti sungai"], answer: 2, solution: "1. Teori konsentris Burgess menggambarkan kota sebagai lingkaran-lingkaran sepusat. 2. Di tengahnya terdapat daerah pusat kegiatan (CBD), dikelilingi zona-zona permukiman yang melingkar ke arah pinggiran. 3. Jadi, jawaban yang benar adalah melingkar dengan pusat kegiatan (CBD) di tengah." },
  { q: "Menurut teori sektoral Hoyt, perkembangan kota membentuk ...", options: ["lingkaran-lingkaran konsentris", "banyak pusat kegiatan", "pola acak", "sektor-sektor (juring) yang berkembang sepanjang jalur transportasi utama"], answer: 3, solution: "1. Hoyt menyempurnakan teori Burgess dengan memperhatikan jalur transportasi. 2. Menurutnya, kegiatan kota berkembang membentuk sektor-sektor atau juring yang memanjang mengikuti jalur transportasi utama seperti jalan raya dan rel kereta. 3. Jadi, jawaban yang benar adalah sektor-sektor (juring) yang berkembang sepanjang jalur transportasi utama." },
  { q: "Teori inti ganda (multiple nuclei) dari Harris dan Ullman menyatakan bahwa struktur ruang kota ...", options: ["memiliki banyak pusat kegiatan yang tumbuh terpisah", "hanya memiliki satu pusat kegiatan", "selalu berbentuk lingkaran sempurna", "berkembang mengikuti satu jalur sungai"], answer: 0, solution: "1. Harris dan Ullman berpendapat kota modern tidak lagi berpusat tunggal. 2. Kota memiliki banyak inti (nuclei) kegiatan yang tumbuh terpisah, misalnya pusat bisnis, kawasan industri, dan pusat pendidikan di lokasi berbeda. 3. Jadi, jawaban yang benar adalah memiliki banyak pusat kegiatan yang tumbuh terpisah." },
  { q: "Pola permukiman desa yang memanjang umumnya terdapat di daerah ...", options: ["dataran tinggi yang luas", "sepanjang jalan raya, rel kereta, atau sungai", "sekitar danau", "puncak gunung"], answer: 1, solution: "1. Pola permukiman memanjang (linear) mengikuti unsur garis di bentang alam. 2. Rumah-rumah berderet sepanjang jalan raya, rel kereta api, sungai, atau garis pantai untuk kemudahan akses. 3. Jadi, jawaban yang benar adalah sepanjang jalan raya, rel kereta, atau sungai." },
  { q: "Urban sprawl adalah ...", options: ["pemadatan penduduk di pusat kota", "pembangunan kembali kawasan kumuh", "perpindahan penduduk desa ke kota", "perluasan fisik kota ke daerah pinggiran yang tidak terkendali"], answer: 3, solution: "1. Urban sprawl adalah gejala perluasan areal perkotaan ke wilayah pinggiran. 2. Perluasan ini terjadi tidak terkendali dan tidak terencana sehingga menggerus lahan pertanian dan menimbulkan masalah lingkungan. 3. Jadi, jawaban yang benar adalah perluasan fisik kota ke daerah pinggiran yang tidak terkendali." },
  { q: "Tujuan utama AMDAL (Analisis Mengenai Dampak Lingkungan) adalah ...", options: ["mengkaji dampak suatu rencana usaha terhadap lingkungan sebelum kegiatan dilaksanakan", "mempercepat perizinan usaha", "menambah pendapatan daerah", "menarik investor"], answer: 0, solution: "1. AMDAL adalah kajian wajib bagi rencana usaha yang berpotensi menimbulkan dampak lingkungan. 2. Tujuannya memprakirakan dan mengevaluasi dampak terhadap lingkungan sebelum kegiatan berjalan agar dapat dicegah atau dikendalikan. 3. Jadi, jawaban yang benar adalah mengkaji dampak suatu rencana usaha terhadap lingkungan sebelum kegiatan dilaksanakan." },
  { q: "Prinsip pembangunan berkelanjutan adalah ...", options: ["memaksimalkan eksploitasi sumber daya alam", "memenuhi kebutuhan masa kini tanpa mengorbankan kebutuhan generasi mendatang", "mengutamakan keuntungan jangka pendek", "memindahkan industri ke desa"], answer: 1, solution: "1. Pembangunan berkelanjutan menyeimbangkan aspek ekonomi, sosial, dan lingkungan. 2. Prinsipnya adalah memenuhi kebutuhan generasi sekarang tanpa mengurangi kemampuan generasi mendatang untuk memenuhi kebutuhannya. 3. Jadi, jawaban yang benar adalah memenuhi kebutuhan masa kini tanpa mengorbankan kebutuhan generasi mendatang." }
  ]
};
